            pg.ellipse(i + Math.floor(world.screenSize[0] / 2), j + Math.floor(world.screenSize[1] / 2), world.screenSize[0] * this.R.next(0.8, 1), world.screenSize[1] * this.R.next(0.8, 1));
            pg.ellipse(i + Math.floor(world.screenSize[0] / 2), j + Math.floor(world.screenSize[1] / 2), world.screenSize[0] * this.R.next(0.8, 1), world.screenSize[1] * this.R.next(0.8, 1));
            pg.noErase();
          }
        } else if (noiseVal > 0.5) {
          for (let u = 0; u < 3; u++) {
            let blockColor = this.R.next(122, 130, true);
            let r = makeRect(pv(i + Math.floor(this.R.next(0, world.screenSize[0] - 1)) + 0.5, j + Math.floor(this.R.next(0, world.screenSize[1] - 1)) + 0.5), { sz: [this.R.next(1, 3, true), this.R.next(1, 3, true)], closed: true });
            pg.noStroke();
            pg.fill(blockColor);
            pg_drawArr(r, pg);
          }
        }

        let chance = this.R.next();
        if (chance > 0.9) {
          let option = this.R.choose([
            [1, 2, 0],
            [2, 1, 0],
            [2, 2, this.R.next(0, 2, true)],
            [2, 3, this.R.next(0, 2, true)],
            [3, 2, this.R.next(0, 2, true)],
            [3, 3, this.R.next(0, 2, true)],
            [4, 3, this.R.next(0, 2, true)],
            [3, 4, this.R.next(0, 2, true)],
            [4, 4, this.R.next(0, 2, true)],
            [5, 4, this.R.next(0, 2, true)],
            [4, 5, this.R.next(0, 2, true)],
          ]);
          for (let y = 2, toggle = false; y < world.screenSize[1] - 2; y += option[1], toggle = !toggle) {
            for (let x = 2; x < world.screenSize[0] - (2 + (toggle ? option[2] : 0)); x += option[0]) {
              let blockColor = this.R.next(122, 130, true);

              let r = makeRect(pv(i + x + 0.5, j + y + 0.5), { sz: [1, 1], closed: false });
              pg.fill(blockColor);
              pg_drawArr(r, pg);
            }
          }
        } else if (chance > 0.8) {
          for (let y = 2, ny = 0; y < world.screenSize[1] - 2; y += 1, ny += 1) {
            for (let x = 2, nx = 0; x < world.screenSize[0] - 2; x += 1, nx += 1) {
              noiseSeed(this.nSeed + i + j + ny + nx);
              let noiseVal = noise(nx * 0.05, ny * 0.05);
              if (noiseVal > 0.55) {
                let r = makeRect(pv(i + x + 0.5, j + y + 0.5), { sz: [1, 1], closed: false });
                let blockColor = this.R.next(122, 130, true);

                pg.fill(blockColor, noiseVal * 255);
                pg_drawArr(r, pg);
              }
            }
          }
        }
      }
    }
    let colors = [];
    for (let i = 2; i < 9; i++) {
      colors.push([120 + i, 120 + i, 120 + i, 255]);
    }

    pg = compressSingleFrame(pg, colors);

    this.main.image(pg, 0, 0);
  }
