    let island = makeRect(islandPt, { sz: [world.screenSize[0] + Math.floor(world.screenSize[0] / 2), world.screenSize[1] + Math.floor(world.screenSize[1] / 2)], closed: true });
    pg_drawArr(island, pg);
    rasterize(pg, { targetColor: [111, 111, 111, 255] });
