    let mote = createPointCircle(pv(Math.floor(this.graphicSize[0] / 2), Math.floor(this.graphicSize[1] / 2)), this.graphicSize[0] / this.R.next(3, 6), this.graphicSize[1] / this.R.next(3, 6), 1, true);

    pg.noStroke();
    let vals = quickNoise({ sz: [this.graphicSize[0], this.graphicSize[1]], nSeed: this.nSeed + 654321, noiseSet: [0.05, 0.05], range: [0, 1], useOffsets: true });
    for (let j = 0; j < pg.height; j += 1) {
      for (let i = 0; i < pg.width; i += 1) {
        let val = vals[j][i];
        if (pointInsideShape(pv(i, j), mote) === true) {
        } else {
          if (val > 0.56) {
            pg.set(i, j, [111, 111, 111, 255]);

            for (let kk = 1; kk < pg.width; kk += 24) {
              if (j === kk || i === kk) {
                pg.set(i, j, [113, 113, 113, 255]);
              }
            }
          }

          if (val > 0.66) {
            pg.set(i, j, [112, 112, 112, 255]);

            for (let kk = 1; kk < pg.width; kk += 24) {
              if (j === kk || i === kk) {
                pg.set(i, j, [113, 113, 113, 255]);
              }
            }
          }
        }
      }
    }

    pg.updatePixels();

    this.main.image(pg, 0, 0);
  }
  addItems() {
    this.R = new Random(tokenData.hash);
    this.R.purge(3000);

    let vals = quickNoise({ sz: [this.main.width, this.main.height], nSeed: this.nSeed + 123456, noiseSet: [0.58, 0.58], range: [0, 1], useOffsets: true });
    let rockSpots = [];
    let shelfSpots = [];
    let orbSpots = [];
    let density = 0.6;
    let mp = pv(this.main.width / 2, this.main.height / 2);
    let maxDist = quickDist(pv(0, 0), mp);
    for (let j = 0; j < this.main.height; j += 1) {
      for (let i = 0; i < this.main.width; i += 1) {
        let val = vals[j][i];
        if (val < density) {
          if (this.R.next() > 0.24) {
            rockSpots.push(pv(i, j));
          }
        } else {
          let mappedDist = _map(quickDist(pv(i, j), mp), 0, maxDist, 0, 1);
          let shelfMap = 1 - easingFunction(1 - mappedDist, 4);
          if (this.R.next() > shelfMap) {
            if (R.next(shelfMap, 1) > 0.89) {
              shelfSpots.push(pv(i, j));
            }
          }

          let orbMap = easingFunction(1 - mappedDist, 4) * 0.98;
          if (this.R.next() > orbMap) {
            if (R.next(0, orbMap) > 0.45) {
              orbSpots.push(pv(i, j));
            }
          }
        }
      }
    }

    if (rockSpots.length > 0) {
      for (let k = rockSpots.length - 1; (k += 0); k--) {
        let pix = this.main.get(rockSpots[k].x, rockSpots[k].y);
        if (pix[0] >= 80 && pix[0] <= 89) {
          this.main.set(rockSpots[k].x, rockSpots[k].y, [pix[0] - 30, pix[1] - 30, pix[2] - 30, 255]);
        }
      }
    }

    if (shelfSpots.length > 0) {
      for (let k = shelfSpots.length - 1; (k += 0); k--) {
        let pix = this.main.get(shelfSpots[k].x, shelfSpots[k].y);
        if (pix[0] >= 80 && pix[0] <= 89) {
          this.main.set(shelfSpots[k].x, shelfSpots[k].y, [201, 201, 201, 255]);
        }
      }
    }

    if (orbSpots.length > 0) {
      for (let k = orbSpots.length - 1; (k += 0); k--) {
        let pix = this.main.get(orbSpots[k].x, orbSpots[k].y);
        if (pix[0] >= 80 && pix[0] <= 89) {
          this.main.set(orbSpots[k].x, orbSpots[k].y, [211, 211, 211, 255]);
        }
      }
    }

    let islandPt = pv(this.mysteryBoxIsland.x * world.screenSize[0], this.mysteryBoxIsland.y * world.screenSize[1]);

    for (let j = islandPt.y + 1; j <= islandPt.y + world.screenSize[1] - 2; j++) {
      for (let i = islandPt.x + 1; i <= islandPt.x + world.screenSize[0] - 2; i++) {
        this.main.set(i, j, [201, 201, 201, 255]);
      }
    }

    let startingShelfSpot = world.screenSpaceToWorldSpace({ screenPos: pv(0, 0), pos: pv(1, 1) });
    this.main.set(startingShelfSpot.x, startingShelfSpot.y, [201, 201, 201, 255]);
    let startingOrb = world.screenSpaceToWorldSpace({ screenPos: pv(0, 0), pos: pv(2, 1) });
    this.main.set(startingOrb.x, startingOrb.y, [211, 211, 211, 255]);

    this.main.updatePixels();
  }

  addScreenType_home(pos) {
    this.clearOutScreen(pos);
    let pg = createGraphics(world.screenSize[0], world.screenSize[1]);
    pg.pixelDensity(1);
    pg.noSmooth();

    for (let j = 1; j < world.screenSize[1] - 1; j += 1) {
      for (let i = 1; i < world.screenSize[0] - 1; i += 1) {
        if (i > 1 && i < world.screenSize[0] - 2 && (j === 2 || j === world.screenSize[1] - 2)) {
          pg.set(i, j, [123, 123, 123, 255]);
        } else if (j > 2 && j < world.screenSize[1] - 2 && (i === 2 || i === world.screenSize[0] - 3)) {
          pg.set(i, j, [123, 123, 123, 255]);
        } else {
          pg.set(i, j, [80, 80, 80, 255]);
        }

        if (i === Math.floor(world.screenSize[0] / 2) || j === Math.floor(world.screenSize[1] / 2)) {
          pg.set(i, j, [80, 80, 80, 255]);
        }
        if (i === Math.floor(world.screenSize[0] / 2) - 2 && j === Math.floor(world.screenSize[1] / 2) - 2) {
          pg.set(i, j, [80, 80, 80, 255]);
        }
      }
    }
    pg.updatePixels();
    this.main.image(pg, pos.x * world.screenSize[0] - pos.x, pos.y * world.screenSize[1] - pos.y);
    pg.remove();
  }
}
