    this.dustCloud = [];
    this.spriteSheet.image(this.createDustCloud({ stage: 0 }), 11 * this.px, 5 * this.px);
    this.spriteSheet.image(this.createDustCloud({ stage: 1 }), 11 * this.px, 6 * this.px);
    this.spriteSheet.image(this.createDustCloud({ stage: 2 }), 11 * this.px, 7 * this.px);
    this.spriteSheet.image(this.createDustCloud({ stage: 3 }), 11 * this.px, 8 * this.px);
  }

  createBaseSpriteSheet() {
