  tester() {
    for (let j = 0; j < this.sz[1]; j += this.px) {
      for (let i = 0; i < this.sz[0]; i += this.px) {
        this.pg.noStroke();
        let r = makeRect(pv(i + this.px / 2, j + this.px / 2), { sz: [this.px, this.px] });
        this.pg.fill(safeRGB([R.next(172, 96), R.next(180, 105), R.next(204, 132)]));
        pg_drawArr(r, this.pg);

        let c = createPointCircle(pv(i + this.px / 2, j + this.px / 2), this.px / 2, this.px / 2, 10, true);
        this.pg.fill(safeRGB([R.next(172, 96), R.next(180, 105), R.next(204, 132)]));
        pg_drawArr(c, this.pg);
      }
    }
  }

