    let cap = makeRect(pv(0, 0), { sz: [this.px * 0.8, this.px * 0.7], closed: true });
    let capBB = getBB(cap);
    translateArr(cap, pv(capBB.mp.x, capBB.p1.y), pv(this.px / 2, 0 + this.px * 0.1));
    pg.fill(accentColor);
    pg.noStroke();
    let sideTop = [pv(0, 0), pv(this.px, 0), cap[1], cap[0]];
    let sideBottom = [cap[3], cap[2], pv(this.px, this.px), pv(0, this.px)];
    let sideLeft = [pv(0, 0), cap[0], cap[3], pv(0, this.px)];
    let sideRight = [pv(this.px, 0), pv(this.px, this.px), cap[2], cap[1]];

    pg.fill(highlightColor);
    pg_drawArr(sideTop, pg);
    pg.fill(shadowColor);
    pg_drawArr(sideBottom, pg);
    pg.fill(mainColor);
    pg_drawArr(sideLeft, pg);
    pg.fill(highlightColor);
    pg_drawArr(sideRight, pg);
    pg.fill(accentColor);
    pg_drawArr(cap, pg);

    pg = compressSingleFrame(pg, [mainColor, accentColor, highlightColor, shadowColor]);
