    pg.stroke(accentColor);
    pg.strokeCap(SQUARE);
    let padding = this.px * 0.05;
    for (let j = padding / 2, count = 0; j < this.px - padding / 2; j += densityY * 1, count++) {
      for (let i = padding; i < this.px - padding; i += padding * densityX) {
        let pt = pv(this.R.next(0, this.px, true), j);
        let ln = [pointFrom(pt, 90, padding * lnLen), pointFrom(pt, -90, padding * lnLen)];
        pg.stroke(accentColor);
        pg_drawArr(ln, pg, { pos: pv(-1, 1) });
        pg.stroke(shadowColor);
        pg_drawArr(ln, pg, { pos: pv(0, 1) });
