  createTileBlock({ mainColor = world.features.colors.tiles.main, accentColor = world.features.colors.tiles.accent, density = 0.25 } = {}) {
    let shadowColor = [mainColor[0] - 20, mainColor[1] - 30, mainColor[2] - 40, 255];
    let subtleOver = [mainColor[0] + 10, mainColor[1] + 12, mainColor[2] + 15, 255];
