    pg.stroke(accentColor);
    pg.strokeCap(SQUARE);
    let lns = [];

    let scalar = this.px * density;

    for (let i = 0; i <= this.px; i += scalar) {
      lns.push([pv(0, Math.round(i)), pv(this.px, Math.round(i))]);
    }
    for (let i = 0; i <= this.px; i += scalar) {
      lns.push([pv(Math.round(i), 0), pv(Math.round(i), this.px)]);
    }

    lns.forEach((a) => {
      pg.stroke(accentColor);
      pg_drawArr(a, pg);
      pg.stroke(shadowColor);
      pg_drawArr(a, pg, { pos: pv(0, 1) });
