  createDugHole({ bg = [234, 180, 0, 255] } = {}) {
    let cols = [bg, [bg[0] - 20, bg[1] - 30, bg[2] - 40, 255], [bg[0] + 10, bg[1] + 10, bg[2] + 0, 255], [bg[0] + 20, bg[1] + 20, bg[2] + 20, 255], [bg[0] - 20, bg[1] - 20, bg[2] - 20, 255]];

    let hole = makeRect(this.baseBB.mp, { sz: [this.baseBB.width * 0.8, this.baseBB.height * 0.6], closed: true });
    hole = refitLineWithSetSpacing(hole, 2);
    soften(hole, { loops: 10, start: -1, end: 1 });
    let bb = getBB(hole);
    let scalarX = getScalar(bb.p1, bb.p2, pv(0, 0), pv(this.px, 0)) * 0.85;
    let scalarY = getScalar(bb.p1, bb.p4, pv(0, 0), pv(0, this.px)) * 0.78;
    scaleArrAxis(hole, bb.mp, scalarX, "x");
    scaleArrAxis(hole, bb.mp, scalarY, "y");
    translateArr(hole, bb.mp, pv(this.px / 2, this.px / 2 + 1));

    let holeClone = cloneArrRecursive(hole)[0];
    translateArr(holeClone, pv(0, 0), pv(0, this.baseBB.height * 0.2));
    let trim1 = trimLineBy(holeClone, { knife: hole });
    let trim2 = trimLineBy(hole, { knife: holeClone });
    holeClone = [...trim1.inside, ...trim2.inside];
    holeClone = mendCurvesAlt(holeClone);
    holeClone = holeClone.sort((a, b) => a.length - b.length)[0];

    let clonePts = [];
    for (let i = 0; i < 200; i++) {
      let pt = findPointInShape(holeClone, { tries: 100, rng: this.R });
      clonePts.push(pt);
    }

    let holePts = [];
    for (let i = 0; i < 200; i++) {
      let pt = findPointInShape(hole, { tries: 100, rng: this.R });
      holePts.push(pt);
    }

    let edgePts = [];
    for (let i = 0; i < 1; i += 0.08) {
      let pt = findPointAlongSpline(hole, i);
      pt.x += this.R.next(-2, 2);
      pt.y += this.R.next(-2, 2);
      edgePts.push(pt);
    }

    let parts = [];
    parts.push(hole);
    parts.push(holePts);
    parts.push(holeClone);
    parts.push(clonePts);
    parts.push(edgePts);

    let bigPG = createGraphics(this.px, this.px);
    bigPG.pixelDensity(1);
    bigPG.noSmooth();

    parts.forEach((a, iterA) => {
      let pg = createGraphics(this.px, this.px);
      pg.pixelDensity(1);
      pg.noSmooth();
      pg.noStroke();
      let col;
      if (iterA === 0) {
        col = cols[1];
        pg.fill(col);
        pg.stroke(col);
        pg.strokeWeight(2);
        pg_drawArr(a, pg);

        pg.noStroke();
        parts[4].forEach((b) => {
          pg.rect(b.x + this.R.next(-2, 2), b.y + this.R.next(-2, 2), 1.9, 1.9);
        });
      } else if (iterA === 1) {
        col = cols[2];
        pg.fill(col);
        a.forEach((b) => {
          pg.rect(b.x, b.y, 1.5, 1.5);
        });
        parts[4].forEach((b) => {
          pg.rect(b.x + this.R.next(-2, 2), b.y + this.R.next(-2, 2), 1.9, 1.9);
        });
      } else if (iterA === 2) {
        col = cols[2];
        pg.fill(col);
        pg_drawArr(a, pg);
        parts[4].forEach((b) => {
          pg.rect(b.x + this.R.next(-2, 2), b.y + this.R.next(-2, 2), 1.9, 1.9);
        });
      } else if (iterA === 3) {
        col = cols[3];
        pg.fill(col);
        a.forEach((b) => {
          pg.rect(b.x, b.y, 1.5, 1.5);
        });
        parts[4].forEach((b) => {
          pg.rect(b.x + this.R.next(-2, 2), b.y + this.R.next(-2, 2), 1.9, 1.9);
        });
      } else if (iterA === 4) {
        col = cols[4];
        pg.fill(col);
        a.forEach((b) => {
          pg.rect(b.x, b.y, 1.5, 1.5);
        });
      }

      pg = compressSingleFrame(pg, [col]);

      bigPG.image(pg, 0, 0);
      pg.remove();
    });
    bigPG.remove();
    return bigPG;
  }

  createRockBlock({ mainColor = world.features.colors.rocks.main, accentColor = world.features.colors.rocks.accent } = {}) {
    mainColor = safeRGB(quantizeColors(mainColor[0] + this.R.next(-30, 30), mainColor[1] + this.R.next(-30, 30), mainColor[2] + this.R.next(-30, 30), { step: 15, max: 255 }));
    accentColor = safeRGB(quantizeColors(mainColor[0] + 40, mainColor[1] + 40, mainColor[2] + 40, { step: 15, max: 255 }));
    let highlightColor = safeRGB(quantizeColors(mainColor[0] + 80, mainColor[1] + 80, mainColor[2] + 80, { step: 15, max: 255 }));
    let pg = createGraphics(this.px, this.px);
    pg.pixelDensity(1);
    pg.noSmooth();
    pg.background(mainColor);
    let blob = makeRect(pv(0, 0), { sz: [100, 100], closed: false });
    blob[0].x -= this.R.next(0, 25);
    blob[1].x += this.R.next(0, 25);
    let bb = getBB(blob);
    closeOpenShape(blob);
    blob = refitLineWithSetSpacing(blob, 4);
    for (let i = 0; i < 30; i++) {
      scalePoint(blob[this.R.next(0, blob.length, true)], pv(bb.mp.x, bb.p1.y), this.R.next(0.5, 1));
    }
    blob = refitLineWithSetSpacing(blob, 4);
    soften(blob, { loops: 90, start: -1, end: 1 });
    bb = getBB(blob);
    rotateShape(blob, bb.mp, 180);
    bb = getBB(blob);

    let scalarX = getScalar(bb.p1, bb.p2, pv(0, 0), pv(this.px, 0)) * 0.95;
    let scalarY = getScalar(bb.p2, bb.p3, pv(0, 0), pv(0, this.px)) * 0.95;
    scaleArrAxis(blob, pv(bb.mp.x, bb.p3.y), scalarX, "x");
    scaleArrAxis(blob, pv(bb.mp.x, bb.p3.y), scalarY, "y");
    translateArr(blob, pv(bb.mp.x, bb.p3.y), pv(this.px / 2, this.px));
    bb = getBB(blob);

    pg.noStroke();
    pg.fill(mainColor);

    pg_drawArr(blob, pg);
    pg.fill(accentColor);

    let clone = cloneArrRecursive(blob)[0];
    scaleArr(clone, bb.mp, 0.9);
    soften(clone, { loops: 0, start: -1, end: 1 });
    pg_drawArr(clone, pg, { pos: pv(0, -this.px * 0.15) });

    scaleArr(clone, bb.mp, 0.8);
    pg.fill(highlightColor);
    pg_drawArr(clone, pg, { pos: pv(0, -this.px * 0.15) });

    for (let k = 0; k < 90; k++) {
      if (this.R.next() > 0.5) {
        pg.fill(accentColor);
      } else {
        pg.fill(mainColor);
      }

      let pt = pv(this.R.next(0, this.px), this.R.next(0, this.px));
      pg.circle(pt.x, pt.y, 2);
    }
    pg = cookieCutter(blob, pg);
    pg = compressSingleFrame(pg, [mainColor, accentColor, highlightColor]);

    let pg3 = createGraphics(this.px, this.px);
    pg3.pixelDensity(1);
    pg3.noSmooth();
    pg3.fill(0, 50);
    pg3.noStroke();
    scaleArrAxis(blob, pv(this.px / 2, this.px), 0.5, "y");
    pg_drawArr(blob, pg3);

    pg3.image(pg, 0, -1);
    pg.remove();
    pg3.remove();
    return pg3;
  }

  createWaterBlock({ deep = false } = {}) {
    let mainColor = world.features.colors.water.main;
    if (deep === true) {
      mainColor = [mainColor[0] - 40, mainColor[1] - 30, mainColor[2] - 40, 255];
    }
    let accentColor = world.features.colors.water.accent;
    let highlightColor = safeRGB(quantizeColors(mainColor[0] + 80, mainColor[1] + 80, mainColor[2] + 80, { step: 15, max: 255 }));
    let pg = createGraphics(this.px, this.px);
    pg.pixelDensity(1);
    pg.noSmooth();
    pg.background(mainColor);
    let freq = this.px * 0.125;
    let wave = createPointCircle(pv(0, 0), freq, freq, 10, false, { start: -60, end: 61 });
    translateArr(wave, wave[0], pv(0, 0));
    pg.strokeWeight(this.px * 0.04);
    pg.stroke(accentColor);
    pg.noFill();
    let toggle = false;
    for (let j = 0, count = 0; j < this.px * 2; j += freq * 2, count++) {
      for (let i = -this.px; i < this.px * 2; i += freq * 2) {
        let offset = pv(0, 0);
        if (count % 2 === 0) {
          offset.x += freq * 0.5;
        }
        pg_drawArr(wave, pg, { pos: pv(i + offset.x, j + offset.y) });
      }
      toggle = !toggle;
    }

    pg = compressSingleFrame(pg, [mainColor, accentColor]);
    pg.remove();
    return pg;
