  createChestBlock({ alt = false, closed = true } = {}) {
    let mainColor = world.features.colors.chest.main;
    if (alt === true) {
      mainColor = world.features.colors.chest.alt;
    }
    let compColor = complimentaryColor(mainColor);
    let stripesColor = safeRGB(quantizeColors(compColor[0] + 80, compColor[1] + 80, compColor[2] + 80, { step: 15, max: 255 }));
    let accentColor = safeRGB(quantizeColors(mainColor[0] + 40, mainColor[1] + 40, mainColor[2] + 40, { step: 15, max: 255 }));
    let highlightColor = safeRGB(quantizeColors(mainColor[0] + 80, mainColor[1] + 80, mainColor[2] + 80, { step: 15, max: 255 }));
    let shadowColor = safeRGB(quantizeColors(mainColor[0] - 20, mainColor[1] - 30, mainColor[2] - 40, { step: 15, max: 255 }));

    let pg = createGraphics(this.px, this.px);

    pg.pixelDensity(1);
    pg.noSmooth();
    pg.background(mainColor);

    pg.stroke(highlightColor);
    pg.strokeWeight(this.px * 0.08);
    let interval = (this.px / 16) * 2;
    for (let k = 0; k < width; k += interval) {
      pg.stroke(stripesColor);
      pg.line(k + interval / 2, 0, k + interval / 2, pg.height);
    }
    pg.noStroke();
    pg.strokeWeight(this.px * 0.04);

    if (closed === true) {
      let box = makeRect(pv(0, 0), { sz: [this.px * 1, this.px * 0.76], closed: true });
      let bb = getBB(box);
      translateArr(box, pv(bb.mp.x, bb.p1.y), pv(this.px / 2, 0));
      pg.fill(shadowColor);
      pg_drawArr(box, pg);
      pg.fill(accentColor);
      bb = getBB(box);
      scaleArr(box, bb.mp, 0.95);
      translateArr(box, pv(0, 0), pv(0, -this.px * 0.1));
      pg_drawArr(box, pg);

      let handle = makeRect(pv(0, 0), { sz: [this.px * 0.4, this.px * 0.1], closed: true });
      translateArr(handle, pv(0, 0), pv(bb.mp.x, bb.mp.y - this.px * 0.1));
      pg.fill(stripesColor);
      pg_drawArr(handle, pg);
      pg.stroke(shadowColor);
      pg.line(handle[0].x, handle[3].y, handle[1].x, handle[2].y);
    } else {
      let box = makeRect(pv(0, 0), { sz: [this.px * 1, this.px * 0.85], closed: true });
      let bb = getBB(box);
      translateArr(box, pv(bb.mp.x, bb.p1.y), pv(this.px / 2, 0));
      pg.fill(highlightColor);
      pg_drawArr(box, pg);
      bb = getBB(box);
      scaleArr(box, bb.mp, 0.88);
      pg.fill(shadowColor);
      pg_drawArr(box, pg);
      bb = getBB(box);
      scaleArrAxis(box, bb.mp, 0.73, "y");
      translateArr(box, box[3], bb.p4);
      pg.fill(accentColor);
      pg_drawArr(box, pg);
    }

    pg.stroke(shadowColor);
    pg.line(0, pg.height, pg.width, pg.height);
    pg.line(0, 0, pg.width, 0);
    pg = compressSingleFrame(pg, [mainColor, accentColor, highlightColor, shadowColor, stripesColor]);
    pg.remove();
    return pg;
  }

  createDustCloud({ stage = 0 }) {
    if (this.dustCloud.length <= 0) {
      for (let i = 0; i < this.px * 4; i++) {
        let pt = pv(this.R.gaussian(this.px / 2, this.px / 5), this.R.gaussian(this.px / 2, this.px / 5));
        this.dustCloud.push(pt);
      }
    }

    let pg = createGraphics(this.px, this.px);

    pg.pixelDensity(1);
    pg.noSmooth();

    pg.noStroke();
    pg.fill(0);
    pg.textAlign(CENTER, CENTER);
    pg.text(stage, 16, 16);

    pg.noStroke();
    pg.fill(255);
    let stageSizer = _map(stage, 0, 3, 1, 0.5);
    this.dustCloud.forEach((a) => {
      let cSize = quickDist(a, pv(this.px / 2, this.px / 2));
      let mapped = _map(cSize, 0, this.px / 2, this.px * 0.2 * stageSizer, 1);
      let shadowMapped = _map(cSize, 0, this.px / 2, 1, 0.25);
      pg.fill(79, 60, 47);
      pg.circle(a.x, a.y + this.px * this.R.next(0.01, 0.1) * shadowMapped, mapped);
      pg.fill(166, 154, 131, 255);
      pg.circle(a.x, a.y, mapped);
    });

    this.dustCloud = this.dustCloud.filter((a) => {
      a.x += R.next(-1 * stageSizer, stageSizer);
      a.y += R.next(-1 * stageSizer, stageSizer);
      return this.R.next() > 0.333;
    });

    pg = compressSingleFrame(pg, [
      [166, 154, 131, 255],
      [125, 106, 79, 255],
      [79, 60, 47, 255],
    ]);
    pg.remove();
    return pg;
  }

  createRaft() {
    let mainColor = safeRGB(quantizeColors(this.R.next(0, 100, true), this.R.next(0, 100, true), this.R.next(0, 100, true), { step: 15, max: 255 }));
    let accentColor = safeRGB(quantizeColors(mainColor[0] + 40, mainColor[1] + 40, mainColor[2] + 40, { step: 15, max: 255 }));
    let highlightColor = safeRGB(quantizeColors(mainColor[0] + 80, mainColor[1] + 80, mainColor[2] + 80, { step: 15, max: 255 }));
    let pg = createGraphics(this.px, this.px);
    pg.pixelDensity(1);
    pg.noSmooth();

    let log = makeRect(pv(0, 0), { sz: [this.px * 0.33, this.px], closed: true });
    log = refitLineWithSetSpacing(log, 2);

    soften(log, { loops: 5, start: -1, end: 1 });
    closeOpenShape(log);
    let bb = getBB(log);
    translateArr(log, pv(bb.mp.x, bb.p3.y), pv(this.px / 2, this.px));
    pg.fill(mainColor);
    pg.noStroke();

    pg_drawArr(log, pg);
    pg_drawArr(log, pg, { pos: pv(-this.px * 0.33, 0) });
    pg_drawArr(log, pg, { pos: pv(this.px * 0.33, 0) });
    let endCap = createPointCircle(pv(0, 0), (this.px * 0.33) / 2, (this.px * 0.33) / 4, 10, true);
    bb = getBB(endCap);
    translateArr(endCap, pv(bb.mp.x, bb.p3.y), pv(this.px / 2, this.px));
    pg.fill(accentColor);
    pg_drawArr(endCap, pg);
    pg_drawArr(endCap, pg, { pos: pv(-this.px * 0.33, 0) });
    pg_drawArr(endCap, pg, { pos: pv(this.px * 0.33, 0) });

    pg.stroke(highlightColor);
    pg.noFill();
    let rope = endCap.slice(endCap.length / 4, endCap.length / 4 + endCap.length / 2);
    pg_drawArr(rope, pg, { pos: pv(0, -this.px * 0.15) });
    pg_drawArr(rope, pg, { pos: pv(-this.px * 0.33, -this.px * 0.15) });
    pg_drawArr(rope, pg, { pos: pv(this.px * 0.33, -this.px * 0.15) });

    pg_drawArr(rope, pg, { pos: pv(0, -this.px * 0.4) });
    pg_drawArr(rope, pg, { pos: pv(-this.px * 0.33, -this.px * 0.4) });
    pg_drawArr(rope, pg, { pos: pv(this.px * 0.33, -this.px * 0.4) });

    pg_drawArr(rope, pg, { pos: pv(0, -this.px * 0.65) });
    pg_drawArr(rope, pg, { pos: pv(-this.px * 0.33, -this.px * 0.65) });
    pg_drawArr(rope, pg, { pos: pv(this.px * 0.33, -this.px * 0.65) });

    pg = compressSingleFrame(pg, [mainColor, accentColor, highlightColor]);
    pg.remove();
    return pg;
  }

  createTreeBlock({ mainColor = world.features.colors.trees.main, accentColor = world.features.colors.trees.accent } = {}) {
    mainColor = safeRGB(quantizeColors(mainColor[0] + this.R.next(-30, 30), mainColor[1] + this.R.next(-30, 30), mainColor[2] + this.R.next(-30, 30), { step: 15, max: 255 }));
    accentColor = safeRGB(quantizeColors(mainColor[0] + 10, mainColor[1] + 20, mainColor[2] + 30, { step: 15, max: 255 }));
    let pg = createGraphics(this.px, this.px);
    pg.pixelDensity(1);
    pg.noSmooth();
    pg.background(mainColor);
    let blob = makeRect(pv(0, 0), { sz: [100, 100], closed: true });
    let bb = getBB(blob);
    blob = refitLineWithSetSpacing(blob, 4);
    for (let i = 0; i < 30; i++) {
      scalePoint(blob[this.R.next(0, blob.length, true)], pv(bb.mp.x, bb.p1.y), this.R.next(0.9, 1));
    }
    blob = refitLineWithSetSpacing(blob, 4);
    soften(blob, { loops: 80, start: -1, end: 1 });
    bb = getBB(blob);
    let scalarX = getScalar(bb.p1, bb.p2, pv(0, 0), pv(this.px, 0)) * 0.95;
    let scalarY = getScalar(bb.p2, bb.p3, pv(0, 0), pv(0, this.px)) * 0.85;
    scaleArrAxis(blob, pv(bb.mp.x, bb.p1.y), scalarX, "x");
    scaleArrAxis(blob, pv(bb.mp.x, bb.p1.y), scalarY, "y");
    translateArr(blob, pv(bb.mp.x, bb.p1.y), pv(this.px / 2, this.px * 0.01));
    bb = getBB(blob);

    pg.noStroke();

    pg.fill(accentColor);
    let clone = cloneArrRecursive(blob)[0];
    scaleArr(clone, bb.mp, 0.9);
    soften(clone, { loops: 50, start: -1, end: 1 });
    pg_drawArr(clone, pg, { pos: pv(0, -this.px * 0.15) });

    for (let k = 0; k < 40; k++) {
      if (this.R.next() > 0.5) {
        pg.fill(accentColor);
      } else {
        pg.fill(mainColor);
      }
      let pt = pv(this.R.next(0, this.px), this.R.next(0, this.px));
      pg.circle(pt.x, pt.y, 2);
    }
    pg = cookieCutter(blob, pg);

    let pg2 = createGraphics(this.px, this.px);
    pg2.pixelDensity(1);
    pg2.noSmooth();

    scaleArrAxis(blob, pv(bb.mp.x, bb.p3.y), 0.5, "y");
    bb = getBB(blob);
    translateArr(blob, pv(bb.mp.x, bb.p3.y), pv(this.px / 2, this.px));

    pg2.noStroke();

    scaleArrAxis(blob, pv(bb.mp.x, bb.p3.y), 0.5, "x");
    let trunkColor = quantizeColors(mainColor[0] - 20, mainColor[1] - 40, mainColor[2] - 80, { step: 15, max: 255 });
    pg2.fill(trunkColor);
    pg_drawArr(blob, pg2, { pos: pv(0, -this.px * 0.01) });

    pg2.image(pg, 0, 0);
    pg2 = compressSingleFrame(pg2, [mainColor, trunkColor, accentColor]);

    let pg3 = createGraphics(this.px, this.px);
    pg3.pixelDensity(1);
    pg3.noSmooth();
    pg3.fill(0, 50);
    pg3.noStroke();
    scaleArrAxis(blob, pv(bb.mp.x, bb.p3.y), 2, "x");

    pg_drawArr(blob, pg3);
    pg.remove();
    pg2.remove();
    pg3.remove();
    pg3.image(pg2, 0, 0);
    return pg3;
  }

  createPlaceholderBlock() {
    let pg = createGraphics(this.px, this.px);
    pg.pixelDensity(1);
    pg.noSmooth();
    pg.background(200, 100, 150);
    pg.remove();
    return pg;
  }
}

class CharacterSprites {
  constructor({ pixelsPerTile = 32, vectorOnly = false } = {}) {
    this.pixelsPerTile = pixelsPerTile;
    this.R = new Random(tokenData.hash);
    this.features = this.calculateFeatures();
    this.headBB = makeBBofSize(pv(200, 200), { w: this.features.headWidth, h: this.features.headHeight });
    let bodyBBHeight = 30;
    this.bodyBB = makeBBofSize(pv(200, this.headBB.p3.y), { w: 200, h: bodyBBHeight });
    this.hairOffset = pv(0, this.features.hairOffset);
    this.eyeSize = this.features.eyeSize;
    this.pupilSize = this.eyeSize * 0.66;
    this.eyeOffset = pv(0, -this.headBB.height * 0.15);
    this.mouthWidth = this.features.mouthWidth;
    this.mouthHeight = this.features.mouthHeight;
    this.legWidth = this.features.legWidth;
    this.legHeight = this.features.legHeight;
    this.armWidth = this.features.armWidth;
    this.armHeight = this.features.armHeight;
    this.bodySoftness = this.features.bodySoftness;
    this.vectorFrames = this.makePoses();
    this.scaleAndFit(this.vectorFrames);
    if (!vectorOnly) {
      this.frames = this.createSprites(this.vectorFrames);
      this.shovelFrames = this.createShovelSprites();
      this.frames.unshift(...this.shovelFrames);
      this.spriteSheet = this.createSpriteSheet(this.frames);
    }
  }

  createSpriteSheet(frames) {
    let pg = createGraphics(this.pixelsPerTile * 4, this.pixelsPerTile * 7);
    pg.pixelDensity(1);
    pg.noSmooth();

    let row = 0;
    let col = 0;
    frames.forEach((a, iterA) => {
      pg.image(a, col * this.pixelsPerTile, row * this.pixelsPerTile);
      col += 1;
      if (col >= 4) {
        row++;
        col = 0;
      }
    });
    pg.remove();
    return pg;
  }

  calculateFeatures() {
    let features = {};
    features.headWidth = this.R.next(70, 120);
    features.headHeight = this.R.next(60, 150);
    features.eyeSize = this.R.next(30, 60, true);
    features.hairOffset = features.headHeight * this.R.next(0, -0.8);
    features.hairWidth = 2;
    features.mouthWidth = features.headWidth * this.R.next(0.33, 0.9);
    features.mouthHeight = features.headHeight * this.R.next(0.1, 0.25);

    features.legWidth = this.R.next(45, 90, true);
    features.legHeight = this.R.next(80, 200, true);
    features.armWidth = 40;
    features.armHeight = this.R.next(60, 120, true);
    features.bodySoftness = 40;

    features.pantsColor = safeRGB([this.R.next(0, 255), this.R.next(0, 255), this.R.next(0, 255)]);
    features.shirtColor = safeRGB([this.R.next(0, 255), this.R.next(0, 255), this.R.next(0, 255)]);
    features.skinColor = safeRGB([this.R.next(0, 255), this.R.next(0, 255), this.R.next(0, 255)]);
    features.hairColor = safeRGB([this.R.next(0, 255), this.R.next(0, 255), this.R.next(0, 255)]);
    return features;
  }

  previewAnimation() {
    image(this.frames[Math.floor(frameCount * 0.1) % this.frames.length], 0, 0, Math.min(width, height) * 0.4, Math.min(width, height) * 0.4);
  }

  makePoses() {
    let frames = [];

    frames.push(this.assemblePose({ eyeOffset: pv(-this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [1, 1], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(-this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 0.8], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(-this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [1, 0.8], armFac: [0.8, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(-this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 1], armFac: [1, 0.8] }));

    frames.push(this.assemblePose({ eyeOffset: pv(this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [1, 1], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 0.8], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [1, 0.8], armFac: [0.8, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(this.headBB.width * 0.25, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 1], armFac: [1, 0.8] }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [1, 1], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 0.8], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [1, 0.8], armFac: [0.8, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 1], armFac: [1, 0.8] }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [1, 1], armFac: [1, 1], up: true }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 0.8], armFac: [1, 1], up: true }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [1, 0.8], armFac: [0.8, 1], up: true }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [0.8, 1], armFac: [1, 0.8], up: true }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 40, stepFac: [1, 1], armFac: [1, 1] }));
    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 20, stepFac: [0.5, 0.5], armFac: [1, 1] }));

    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 135, stepFac: [1, 1], armFac: [1, 1] }));
    frames.push(this.assemblePose({ eyeOffset: pv(0, this.eyeOffset.y), armRotation: 140, stepFac: [0.8, 0.8], armFac: [1, 1] }));

    let megaBB = [];
    frames.forEach((a) => {
      Object.keys(a).forEach((b) => {
        a[b].forEach((c) => {
          megaBB.push(getBB(c));
        });
      });
    });

    megaBB = combineBB(megaBB);

    this.megaBB = megaBB;

    return frames;
  }

  scaleAndFit(frames) {
    let scalar = motherGloveScalar(this.megaBB, { motherBB: makeBBofSize(pv(0, 0), { w: this.pixelsPerTile, h: this.pixelsPerTile }) }) * 0.9;
    frames.forEach((a) => {
      let bb = [];
      Object.keys(a).forEach((b) => {
        scaleArr(a[b], this.megaBB.mp, scalar, true);
        translateArr(a[b], this.megaBB.mp, pv(this.pixelsPerTile / 2, this.pixelsPerTile / 2), true);
        bb.push(getBBC(a[b]));
      });
      bb = combineBB(bb);
      Object.keys(a).forEach((b) => {
        translateArr(a[b], pv(bb.mp.x, bb.p3.y), pv(this.pixelsPerTile / 2, this.pixelsPerTile - 1), true);
      });
    });
  }

  createSprites(vectorFrames) {
    let frames = [];
    vectorFrames.forEach((a, iterA) => {
      let framePG = createGraphics(this.pixelsPerTile, this.pixelsPerTile);
      framePG.pixelDensity(1);
      framePG.noSmooth();

      Object.keys(a).forEach((b) => {
        let fillColors = [];
        let strokeColors = [];
        let pg = createGraphics(this.pixelsPerTile, this.pixelsPerTile);
        pg.pixelDensity(1);
        pg.noSmooth();

        if (b === "head") {
          fillColors.push(this.features.skinColor);
          pg.fill(fillColors[0]);
        } else if (b === "eyes") {
          fillColors.push([255, 255, 255, 255]);

          pg.fill(fillColors[0]);
        } else if (b === "pupils") {
          fillColors.push([0, 0, 0, 255]);
          pg.fill(fillColors[0]);
        } else if (b === "mouth") {
          fillColors.push([255, 0, 0, 255]);

          pg.fill(fillColors[0]);
        } else if (b === "arms") {
          fillColors.push(this.features.shirtColor);

          pg.fill(fillColors[0]);
        } else if (b === "legs") {
          fillColors.push(this.features.pantsColor);

          pg.fill(fillColors[0]);
        } else if (b === "hair") {
          fillColors.push(this.features.hairColor);
          pg.fill(fillColors[0]);
        }
        a[b].forEach((c) => {
          pg_drawArr(c, pg);
        });

        pg = compressSingleFrame(pg, fillColors);
        if (strokeColors.length > 0) {
          pg = outlineFrame(pg, { col: strokeColors[0] });
        }
        framePG.image(pg, 0, 0);
        pg.remove();
      });

      framePG = outlineFrame(framePG, { col: [0, 0, 0, 255] });
      let withShadow = createGraphics(this.pixelsPerTile, this.pixelsPerTile);
      withShadow.pixelDensity(1);
      withShadow.noSmooth();
      withShadow.fill(0, 100);
      withShadow.noStroke();

      withShadow.ellipse(framePG.width / 2, framePG.height - framePG.height * 0.1, framePG.width * 0.6, framePG.height * 0.1);

      withShadow.image(framePG, 0, 0);
      framePG.remove();
      withShadow.remove();
      frames.push(withShadow);
    });
    return frames;
  }

  assemblePose({ eyeOffset = pv(0, 0), armRotation = 40, stepFac = [1, 1], armFac = [1, 1], up = false } = {}) {
    let parts = {};

    if (up === true) {
      parts.mouth = this.makeMouth();
      parts.eyes = this.makeEyes({ offset: eyeOffset });

      parts.head = this.makeHead();
      parts.hair = this.makeHair();
      parts.legs = this.makeLegs({ stepFac: stepFac });
      parts.arms = this.makeArms({ armRotation: armRotation, armFac: armFac });
    } else {
      parts.hair = this.makeHair();
      parts.head = this.makeHead();
      parts.mouth = this.makeMouth();
      parts.eyes = this.makeEyes({ offset: eyeOffset });
      parts.pupils = this.makePupils({ offset: eyeOffset });
      parts.arms = this.makeArms({ armRotation: armRotation, armFac: armFac });
      parts.legs = this.makeLegs({ stepFac: stepFac });
    }
    return parts;
  }

  makeMouth() {
    let parts = [];
    parts.push(createPointCircle(pv(this.headBB.mp.x, this.headBB.mp.y + this.headBB.height * 0.25), this.mouthWidth, this.mouthHeight, 10, true));
    return parts;
  }

  makeEyes({ offset = pv(0, 0) } = {}) {
    let parts = [];
    parts.push(createPointCircle(pv(this.headBB.p1.x + offset.x, this.headBB.p1.y + this.headBB.height * 0.25 + offset.y), this.eyeSize, this.eyeSize, 10, true));
    parts.push(createPointCircle(pv(this.headBB.p2.x + offset.x, this.headBB.p2.y + this.headBB.height * 0.25 + offset.y), this.eyeSize, this.eyeSize, 10, true));
    return parts;
  }

  makePupils({ offset = pv(0, 0) } = {}) {
    let parts = [];
    parts.push(createPointCircle(pv(this.headBB.p1.x + offset.x + offset.x * 0.5, this.headBB.p1.y + this.headBB.height * 0.25 + offset.y), this.pupilSize, this.pupilSize, 10, true));
    parts.push(createPointCircle(pv(this.headBB.p2.x + offset.x + offset.x * 0.5, this.headBB.p2.y + this.headBB.height * 0.25 + offset.y), this.pupilSize, this.pupilSize, 10, true));
    return parts;
  }

  makeHead() {
    let parts = [];
    parts.push(makeRect(pv(this.headBB.mp.x, this.headBB.mp.y), { sz: [this.headBB.width * 2, this.headBB.height], closed: true }));
    closeOpenShape(parts[0]);
    parts[0] = refitLineWithSetSpacing(parts[0], 2);
    soften(parts[0], { loops: this.bodySoftness, start: -1, end: 1 });
    closeOpenShape(parts[0]);
    return parts;
  }

  makeHair() {
    let parts = [];
    parts.push(makeRect(pv(this.headBB.mp.x + this.hairOffset.x, this.headBB.mp.y + this.hairOffset.y), { sz: [this.headBB.width * this.features.hairWidth, this.headBB.height], closed: true }));

    shiftArrayIndexes(parts[0], 2);

    parts[0] = refitLineWithSetSpacing(parts[0], 2);
    soften(parts[0], { loops: 300, start: 1, end: -1 });

    return parts;
  }

  makeLegs({ stepFac = [1, 1] } = {}) {
    let parts = [];
    parts.push(makeRect(pv(this.bodyBB.p4.x + this.legWidth / 2, this.bodyBB.p4.y + this.legHeight / 2), { sz: [this.legWidth, this.legHeight * stepFac[0]], closed: true }));
    parts.push(makeRect(pv(this.bodyBB.p3.x - this.legWidth / 2, this.bodyBB.p3.y + this.legHeight / 2), { sz: [this.legWidth, this.legHeight * stepFac[1]], closed: true }));
    parts.push([findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.25), findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.75), parts[1][1], this.bodyBB.p3, parts[1][2], parts[1][3], quickMp(parts[1][3], parts[1][0]), quickMp(parts[0][2], parts[0][1]), parts[0][2], parts[0][3], parts[0][0]]);

    closeOpenShape(parts[parts.length - 1]);
    parts[parts.length - 1] = refitLineWithSetSpacing(parts[parts.length - 1], 2);
    soften(parts[parts.length - 1], { loops: this.bodySoftness, start: -1, end: 1 });
    closeOpenShape(parts[parts.length - 1]);
    parts = [parts[parts.length - 1]];
    return parts;
  }

  makeArms({ armRotation = 20, armFac = [1, 1] } = {}) {
    let armHeight = this.armHeight * _map(armRotation, 0, 180, 1, 0.5);
    let parts = [];
    parts.push(makeRect(pv(0, 0), { sz: [this.armWidth, armHeight * armFac[0]], closed: true, rotationAmt: armRotation }));
    translateArr(parts[parts.length - 1], findPointAlongSpline([parts[parts.length - 1][0], parts[parts.length - 1][1]], _map(armRotation, 0, 180, 0, 1)), this.bodyBB.p1);
    parts.push(makeRect(pv(0, 0), { sz: [this.armWidth, armHeight * armFac[1]], closed: true, rotationAmt: -armRotation }));
    translateArr(parts[parts.length - 1], findPointAlongSpline([parts[parts.length - 1][0], parts[parts.length - 1][1]], _map(armRotation, 0, 180, 1, 0)), this.bodyBB.p2);
    let left = parts[parts.length - 2];
    let right = parts[parts.length - 1];
    if (armRotation > 90) {
      parts.push([findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.25), pv(this.bodyBB.mp.x, this.bodyBB.p1.y), findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.75), right[1], right[2], right[3], right[4], this.bodyBB.p3, this.bodyBB.p4, left[1], left[2], left[3], left[4]]);
    } else if (parts[parts.length - 2][2].x < this.bodyBB.p1.x) {
      parts.push([findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.25), pv(this.bodyBB.mp.x, this.bodyBB.p1.y), findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.75), right[1], right[2], right[3], right[4], this.bodyBB.p3, this.bodyBB.p4, left[1], left[2], left[3], left[4]]);
    } else {
      parts.push([findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.25), pv(this.bodyBB.mp.x, this.bodyBB.p1.y), findPointAlongSpline([this.bodyBB.p1, this.bodyBB.p2], 0.75), right[1], right[2], right[3], right[4], left[1], left[2], left[3], left[4]]);
    }

    closeOpenShape(parts[parts.length - 1]);
    parts[parts.length - 1] = refitLineWithSetSpacing(parts[parts.length - 1], 2);
    soften(parts[parts.length - 1], { loops: this.bodySoftness, start: -1, end: 1 });
    closeOpenShape(parts[parts.length - 1]);

    parts = [parts[parts.length - 1]];
    return parts;
  }

  createShovelSprites() {
    let sprites = [];
    sprites.push(this.makeShovel("right", 0));
    sprites.push(this.makeShovel("right", 1));
    sprites.push(this.makeShovel("left", 0));
    sprites.push(this.makeShovel("left", 1));
    sprites.push(this.makeShovel("down", 0));
    sprites.push(this.makeShovel("down", 1));
    sprites.push(this.makeShovel("up", 0));
    sprites.push(this.makeShovel("up", 1));
    return sprites;
  }

  makeShovel(type = "left", f = 1) {
    let bb = makeBBofSize(pv(200, 200), { w: 200, h: 200 });
    let ang;
    let fulcrum;
    let postScalar;
    if (type === "right") {
      ang = f === 0 ? -75 : -125;
      fulcrum = pv(bb.mp.x - bb.width * 0.25, bb.mp.y);
      postScalar = 0.9;
    } else if (type === "left") {
      ang = f === 0 ? 75 : 125;
      fulcrum = pv(bb.mp.x + bb.width * 0.25, bb.mp.y);
      postScalar = 0.9;
    } else if (type === "down") {
      ang = 0;
      fulcrum = pv(bb.mp.x, bb.mp.y - bb.height * 0.25);
      postScalar = f === 0 ? 0.8 : 0.65;
    } else if (type === "up") {
      ang = 180;
      fulcrum = pv(bb.mp.x, bb.mp.y + bb.height * 0.25);
      postScalar = f === 0 ? 0.65 : 0.8;
    }

    let post = [pointFrom(fulcrum, ang, 100 * postScalar), pointFrom(fulcrum, ang + 180, 20 * postScalar)];

    let handle = [bb.p1, bb.p4, bb.p3, bb.p2];
    handle = refitLineWithSetSpacing(handle, 10);
    soften(handle, { loops: 20, start: 1, end: -1 });
    closeOpenShape(handle);
    translateArr(handle, pv(bb.mp.x, bb.p3.y), bb.mp);
    scaleArrAxis(handle, bb.mp, mapTriLinear(Math.abs(ang), 0, 180, 0.2, 0.05), "x");
    scaleArrAxis(handle, bb.mp, mapTriLinear(splineDist(post), 0, 120, 0.1, 0.05), "y");
    rotateShape(handle, bb.mp, pointAng(post[1], post[0]));
    translateArr(handle, bb.mp, post[1]);

    let bucketLeft = [bb.p1, pv(bb.p1.x, bb.mp.y + 20), pv(bb.mp.x - 40, bb.p3.y), pv(bb.mp.x, bb.p3.y)];
    bucketLeft = refitLineWithSetSpacing(bucketLeft, 10);
    soften(bucketLeft, { loops: 20 });

    let bucketRight = cloneArrRecursive(bucketLeft)[0];
    scaleArrAxis(bucketRight, bb.mp, -1, "x");

    let bucketScoop = [bb.p1, pv(bb.p1.x + 30, bb.p1.y + 30), pv(bb.p2.x - 30, bb.p2.y + 30), bb.p2];
    bucketScoop = refitLineWithSetSpacing(bucketScoop, 10);
    soften(bucketScoop, { loops: 20 });

    let shovel = [...bucketLeft, ...bucketRight.reverse(), ...bucketScoop.reverse()];
    translateArr(shovel, pv(bb.mp.x, bb.p2.y + 30), bb.mp);
    scaleArrAxis(shovel, bb.mp, mapTriLinear(Math.abs(ang), 0, 180, 0.4, 0.2), "x");
    scaleArrAxis(shovel, bb.mp, mapTriLinear(splineDist(post), 0, 120, 0.45, 0.1), "y");
    rotateShape(shovel, bb.mp, pointAng(post[1], post[0]));
    translateArr(shovel, bb.mp, post[0]);

    let scalar = getScalar(bb.p1, bb.p2, pv(0, 0), pv(0, this.pixelsPerTile));

    let parts = [post, handle, shovel];
    scaleArr(parts, bb.mp, scalar, true);
    translateArr(parts, bb.mp, pv(this.pixelsPerTile / 2, this.pixelsPerTile / 2), true);

    let pg = createGraphics(this.pixelsPerTile, this.pixelsPerTile);
    pg.pixelDensity(1);
    pg.noSmooth();
    parts.forEach((a, iterA) => {
      pg.strokeWeight(this.pixelsPerTile * 0.08);
      if (iterA === 0) {
        pg.stroke(113, 66, 29);
        pg.noFill();
      } else if (iterA === 1) {
        pg.strokeWeight(2);

        pg.stroke(113, 66, 29);
        pg.noFill();
      } else if (iterA === 2) {
        pg.fill(180, 180, 180);
        pg.noStroke();
      }

      pg_drawArr(a, pg);
    });

    pg = compressSingleFrame(pg, [
      [113, 66, 29, 255],
      [180, 180, 180, 255],
    ]);

    pg = outlineFrame(pg, { col: [0, 0, 0, 255] });

    pg.remove();
    return pg;

    return parts;
  }
}

function mapTriLinear(x, fromStart, fromEnd, low, high) {
  if (fromStart === fromEnd) return low;
  const t = (x - fromStart) / (fromEnd - fromStart);
  const v = Math.max(0, 1 - Math.abs(2 * t - 1));
  return low + v * (high - low);
}

function mapQuadratic(x, fromStart, fromEnd, low, high) {
  if (fromStart === fromEnd) return low;
  const t = (x - fromStart) / (fromEnd - fromStart);
  const v = Math.max(0, 1 - (2 * t - 1) ** 2);
  return low + v * (high - low);
}
class Master {
  constructor() {
    world.setWorldTile({ screenPos: world.spawnScreen, pos: world.spawnPt, tileType: 80 });

    this.screen = new Screen(world.spawnScreen, { startPos: world.spawnPt });
    this.screen.recordScreenToVisited(this.screen.data.screenPos);

    this.exitData = { movingTowardExit: false, exitDir: undefined, screenShiftActive: false, screenShiftTimer: 0, sendCommand: false };
  }

  prepareNextScreen(pos = pv(1, 2), { playerStartPos = pv(1, 1) } = {}) {
    this.nextScreen = new Screen(pos, { startPos: playerStartPos });
  }

  displayScreen() {
    if (this.exitData.screenShiftActive === true) {
      this.shiftScreens();
    } else {
      this.screen.display();
    }
  }

  shiftScreens() {
    this.exitData.screenShiftTimer += 0.01;
    if (this.exitData.screenShiftTimer >= 1) {
      this.exitData.screenShiftTimer = 0;
      this.exitData.screenShiftActive = false;
      this.exitData.movingTowardExit = false;
      this.screen = this.nextScreen;

      this.screen.recordScreenToVisited(this.screen.data.screenPos);

      if (this.exitData.exitDir === "north") {
        player.path[player.path.length - 1] = pv(player.path[player.path.length - 1].x, world.screenSize[1] - 1);
        player.path[player.path.length - 2] = pv(player.path[player.path.length - 1].x, world.screenSize[1]);
      } else if (this.exitData.exitDir === "east") {
        player.path[player.path.length - 1] = pv(0, player.path[player.path.length - 1].y);
        player.path[player.path.length - 2] = pv(-1, player.path[player.path.length - 1].y);
      } else if (this.exitData.exitDir === "south") {
        player.path[player.path.length - 1] = pv(player.path[player.path.length - 1].x, 0);
        player.path[player.path.length - 2] = pv(player.path[player.path.length - 1].x, -1);
      } else if (this.exitData.exitDir === "west") {
        player.path[player.path.length - 1] = pv(world.screenSize[0] - 1, player.path[player.path.length - 1].y);
        player.path[player.path.length - 2] = pv(world.screenSize[0], player.path[player.path.length - 1].y);
      }
      player.positionToggle = false;

      player.pos.tweened = master.screen.getCellCoords(player.path[player.path.length - 2]);

      this.exitData.exitDir = undefined;

      this.screen.display();
      return;
    }

    let screenWidth = this.screen.data.cellSize * world.screenSize[0];
    let screenHeight = this.screen.data.cellSize * world.screenSize[1];

    if (this.exitData.exitDir === "north") {
      this.screen.display(pv(0, screenHeight * this.exitData.screenShiftTimer));
      this.nextScreen.display(pv(0, -screenHeight * (1 - this.exitData.screenShiftTimer)));
      this.screen.drawCellTweened(pv(player.pos.tweened.x, player.pos.tweened.y + screenHeight * this.exitData.screenShiftTimer));
    } else if (this.exitData.exitDir === "east") {
      this.screen.display(pv(-screenWidth * this.exitData.screenShiftTimer, 0));
      this.nextScreen.display(pv(screenWidth * (1 - this.exitData.screenShiftTimer), 0));
      this.screen.drawCellTweened(pv(player.pos.tweened.x - screenWidth * this.exitData.screenShiftTimer, player.pos.tweened.y));
    } else if (this.exitData.exitDir === "south") {
      this.screen.display(pv(0, -screenHeight * this.exitData.screenShiftTimer));
      this.nextScreen.display(pv(0, screenHeight * (1 - this.exitData.screenShiftTimer)));
      this.screen.drawCellTweened(pv(player.pos.tweened.x, player.pos.tweened.y - screenHeight * this.exitData.screenShiftTimer));
    } else if (this.exitData.exitDir === "west") {
      this.screen.display(pv(screenWidth * this.exitData.screenShiftTimer, 0));
      this.nextScreen.display(pv(-screenWidth * (1 - this.exitData.screenShiftTimer), 0));
      this.screen.drawCellTweened(pv(player.pos.tweened.x + screenWidth * this.exitData.screenShiftTimer, player.pos.tweened.y));
    }
  }

  examineRow(rowNumber, gridBin) {
    let stops = [];
    let row = gridBin[rowNumber];
    for (let i = 0; i < row.length; i++) {
      let prev = row[i - 1];
      let next = row[i + 1];

      if (prev === undefined || next === undefined) {
        if (row[i] !== 1) {
          if (!stops.includes(i)) {
            stops.push(i);
          }
        }
      }
      if (row[i + 1] === 1 || row[i - 1] === 1) {
        if (row[i] !== 1) {
          if (!stops.includes(i)) {
            stops.push(i);
          }
        }
      }
    }

    return stops;
  }

  gatherMapIntel({ startPos = pv(0, 0), gridBin = [] } = {}) {
    this.safeCells = floodFill(startPos, gridBin);
  }

  createZenPath(gridBin, { transpose = false, reverse = false } = {}) {
    let clone = structuredClone(gridBin);

    if (transpose === true) {
      clone = transposeArr(clone);
    }

    let allStops = [];
    for (let j = 0; j < clone.length; j++) {
      let rowStops = [];
      let row = clone[j];
      let bin = [];
      for (let i = 0; i < clone[j].length; i++) {
        let prev = row[i - 1];
        let next = row[i + 1];
        let north, south;
        if (j > 0 && j < clone.length - 1) {
          north = clone[j - 1][i];
          south = clone[j + 1][i];
        }

        if (prev === undefined || next === undefined) {
          if (row[i] !== 1) {
            if (arrIncludesPt(rowStops, pv(i, j)) === false) {
              rowStops.push(pv(i, j));
            }
          }
        }
        if (row[i + 1] === 1 || row[i - 1] === 1) {
          if (row[i] !== 1) {
            if (arrIncludesPt(rowStops, pv(i, j)) === false) {
              rowStops.push(pv(i, j));
              if (bin.length > 0) {
                rowStops.splice(rowStops.length - 1, 0, ...bin);
                bin = [];
              }
            }
          }
        }
        if (north === 0 && south === 0 && prev === 0 && next === 0 && row[i] === 1 && i > 0 && i < row.length - 1) {
          let northEast = clone[j - 1][i + 1];
          let northWest = clone[j - 1][i - 1];
          let southEast = clone[j + 1][i + 1];
          let southWest = clone[j + 1][i - 1];
          if (northEast === 0 && northWest === 0 && southEast === 0 && southWest === 0) {
            bin.push(pv(i - 1, j));
            bin.push(pv(i - 1, j + 1));
            bin.push(pv(i, j + 1));
            bin.push(pv(i + 1, j + 1));
            bin.push(pv(i + 1, j));
            bin.push(pv(i + 1, j - 1));
            bin.push(pv(i, j - 1));
            bin.push(pv(i - 1, j - 1));
            bin.push(pv(i - 1, j));
          }
          if (R.next() > 0.5) {
            bin.reverse();
          }
        }
      }
      if (j % 2 !== 0) {
        rowStops.reverse();
      }
      allStops.push(...rowStops);
    }

    if (transpose === true) {
      allStops = allStops.map((a) => {
        return pv(a.y, a.x);
      });
    }
    if (reverse === true) {
      allStops.reverse();
    }

    return allStops;
  }

  calculatePathTo(player, endPos, gridBin) {
    let startPos = player.pos.current;
    let path = aStar(startPos, endPos, gridBin);
    return path;
  }

  assignPathToItem(item, gridBin) {
    let startPos = player.pos.current;
    let endPos = item.pos;
    let path = aStar(startPos, endPos, gridBin);
    return path;
  }

  assignRandomPath(player, gridBin) {
    let startPos = player.pos.current;
    let endPos = pv(R.next(0, gridBin[0].length, true), R.next(0, gridBin.length, true));

    while (gridBin[endPos.y][endPos.x] === 1) {
      endPos = pv(R.next(0, gridBin[0].length, true), R.next(0, gridBin.length, true));
    }
    let path = aStar(startPos, endPos, gridBin);

    let verbalCommands = [];

    for (let i = 0; i < path.length - 1; i++) {
      if (path[i + 1].x > path[i].x) {
        verbalCommands.push("right");
      } else if (path[i + 1].x < path[i].x) {
        verbalCommands.push("left");
      } else if (path[i + 1].y > path[i].y) {
        verbalCommands.push("down");
      } else if (path[i + 1].y < path[i].y) {
        verbalCommands.push("up");
      }
    }
    return verbalCommands;
    return path;
  }

  calculatePathToExit(player, gridBin) {
    if (this.screen.exits.length <= 0) {
      return [];
    }
    let endPos = this.screen.exits[R.next(0, this.screen.exits.length, true)];
    let path = this.calculatePathTo(player, endPos, gridBin);
    if (endPos.x === 0) {
      path.push(pv(path[path.length - 1].x - 1, path[path.length - 1].y));
      this.exitData.exitDir = "west";
    } else if (endPos.x === world.screenSize[0] - 1) {
      path.push(pv(path[path.length - 1].x + 1, path[path.length - 1].y));
      this.exitData.exitDir = "east";
    } else if (endPos.y === 0) {
      path.push(pv(path[path.length - 1].x, path[path.length - 1].y - 1));
      this.exitData.exitDir = "north";
    } else if (endPos.y === world.screenSize[1] - 1) {
      path.push(pv(path[path.length - 1].x, path[path.length - 1].y + 1));
      this.exitData.exitDir = "south";
    }
    this.exitData.movingTowardExit = true;

    let verbalCommands = [];
    for (let i = 0; i < path.length - 1; i++) {
      if (path[i + 1].x > path[i].x) {
        verbalCommands.push("right");
      } else if (path[i + 1].x < path[i].x) {
        verbalCommands.push("left");
      } else if (path[i + 1].y > path[i].y) {
        verbalCommands.push("down");
      } else if (path[i + 1].y < path[i].y) {
        verbalCommands.push("up");
      }
    }
    return verbalCommands;
    return path;
  }

  displayScreenFrame() {
    fill(world.screenFrameColor);
    noStroke();
    rect(0, 0, width, this.screen.data.offset.y);
    rect(0, 0, this.screen.data.offset.x, height);
    rect(this.screen.data.offset.x + this.screen.pg.width * this.screen.data.scalar, 0, width - this.screen.data.offset.x - this.screen.pg.width * this.screen.data.scalar, height);
    rect(0, this.screen.data.offset.y + this.screen.pg.height * this.screen.data.scalar, width, height - this.screen.data.offset.y - this.screen.pg.height * this.screen.data.scalar);
  }
}
