          }
        } else if (this.itemToPickup.data.itemType === "shelfBox") {
          if (this.itemBag.cabinets.length < this.itemBag.maxCabinetsAllowed) {
            this.itemToPickup.pickupItem();
            this.animationFreeze.active = true;
            this.animationFreeze.type = "show";
            this.animationFreeze.disableUserControl = true;
          } else {
            this.showInventoryFull = true;
          }
        }
      }
    } else {
      this.animationFreeze.type = "crouch";
      this.animationFreeze.active = true;
      this.animationFreeze.disableUserControl = true;
    }
  }

  moveStep(direction = undefined, { turnFace = false } = {}) {
    if (master.exitData.screenShiftActive === false) {
      this.checkForItemPickup();

      if (this.isIdle === true && direction !== undefined) {
        let path = [];
        this.isIdle = false;
        this.timer = 0;
        this.positionToggle = true;
        if (direction === "right") {
          path.push(this.pos.current);
          if (turnFace === true) {
            path.push(this.pos.current);
          } else {
            path.push(pv(this.pos.current.x + 1, this.pos.current.y));
          }
          this.playerFacingDir = -90;
        } else if (direction === "left") {
          path.push(this.pos.current);
          if (turnFace === true) {
            path.push(this.pos.current);
          } else {
            path.push(pv(this.pos.current.x - 1, this.pos.current.y));
          }
          this.playerFacingDir = 90;
        } else if (direction === "up") {
          path.push(this.pos.current);
          if (turnFace === true) {
            path.push(this.pos.current);
          } else {
            path.push(pv(this.pos.current.x, this.pos.current.y - 1));
          }
          this.playerFacingDir = -180;
        } else if (direction === "down") {
          path.push(this.pos.current);
          if (turnFace === true) {
            path.push(this.pos.current);
          } else {
            path.push(pv(this.pos.current.x, this.pos.current.y + 1));
          }
          this.playerFacingDir = 0;
        }

        let worldSpace = world.screenSpaceToWorldSpace({ screenPos: master.screen.data.screenPos, pos: path[1] });
        let worldEdge = worldSpace.x < 0 || worldSpace.x >= world.worldSize[0] * world.screenSize[0] || worldSpace.y < 0 || worldSpace.y >= world.worldSize[1] * world.screenSize[1];

        if (worldEdge === true) {
          path = [];
          this.isIdle = true;
          this.timer = 0;
          return;
        }

        this.pos.front = getFacingCell(this.playerFacingDir, this.pos.current);

        this.path = path;

        if (this.path[1].x < 0 || this.path[1].x >= world.screenSize[0] || this.path[1].y < 0 || this.path[1].y >= world.screenSize[1]) {
        } else {
          this.nextTileType = master.screen.bin[path[1].y][path[1].x];
          this.nextTilePos = path[1];
          if (world.tileCodes.blocked.includes(this.nextTileType)) {
            path = [];
            this.isIdle = true;
            this.timer = 0;
            return;
          } else {
            this.stepSound();
          }
        }

        this.trailToggle = false;

        if (this.trailToggle === true) {
          let enterFrom = pointAng(this.pathHistory[this.pathHistory.length - 1], this.path[0]);
          let exitTo = pointAng(this.path[0], this.path[1]);
          let horz = [-90, 90];
          let vert = [-180, 180, 0];
          let tileType = 24;

          if (world.tileCodes.nonRakable.includes(master.screen.bin[this.pos.current.y][this.pos.current.x])) {
            return;
          }

          let itemExistsHere = world.tileCodes.arrangeableItem.includes(master.screen.bin[this.pos.current.y][this.pos.current.x]);
          if ((enterFrom === -90 && exitTo === -90) || (enterFrom === 90 && exitTo === 90)) {
            tileType = 22;
          } else if ((enterFrom === 0 && exitTo === 0) || (enterFrom === -180 && exitTo === -180)) {
            tileType = 24;
          } else if (enterFrom === 90 && exitTo === -90) {
            tileType = 21;
          } else if (enterFrom === -90 && exitTo === 90) {
            tileType = 23;
          } else if (enterFrom === -180 && exitTo === 0) {
            tileType = 20;
          } else if (enterFrom === 0 && exitTo === -180) {
            tileType = 28;
          } else if ((enterFrom === -180 && exitTo === -90) || (enterFrom === 90 && exitTo === 0)) {
            tileType = 25;
          } else if ((enterFrom === -90 && exitTo === -180) || (enterFrom === 0 && exitTo === 90)) {
            tileType = 30;
          } else if ((enterFrom === 0 && exitTo === -90) || (enterFrom === 90 && exitTo === -180)) {
            tileType = 29;
          } else if ((enterFrom === -180 && exitTo === 90) || (enterFrom === -90 && exitTo === -0)) {
            tileType = 26;
          }
          if (itemExistsHere === true) {
            tileType += 20;
          }

          this.markTrail(tileType);
        }

        this.pos.tweened = this.getTweenPos(this.path[0], this.path[1], this.timer);
      } else if (this.isIdle === true && direction === undefined) {
        this.pos.front = getFacingCell(this.playerFacingDir, this.pos.current);
      } else {
        this.timer += this.playerSpeed;

        if (this.timer > 0.5) {
          if (this.path[1].x < 0 || this.path[1].x >= world.screenSize[0] || this.path[1].y < 0 || this.path[1].y >= world.screenSize[1]) {
            if (this.path[1].x === -1) {
              master.exitData.exitDir = "west";
              master.prepareNextScreen(pv(master.screen.data.screenPos.x - 1, master.screen.data.screenPos.y), { playerStartPos: pv(world.screenSize[0] - 1, this.path[this.path.length - 1].y) });
            } else if (this.path[1].x === world.screenSize[0]) {
              master.exitData.exitDir = "east";
              master.prepareNextScreen(pv(master.screen.data.screenPos.x + 1, master.screen.data.screenPos.y), { playerStartPos: pv(0, this.path[this.path.length - 1].y) });
            } else if (this.path[1].y === -1) {
              master.exitData.exitDir = "north";

              master.prepareNextScreen(pv(master.screen.data.screenPos.x, master.screen.data.screenPos.y - 1), { playerStartPos: pv(this.path[this.path.length - 1].x, world.screenSize[1] - 1) });
            } else if (this.path[1].y === world.screenSize[1]) {
              master.exitData.exitDir = "south";
              master.prepareNextScreen(pv(master.screen.data.screenPos.x, master.screen.data.screenPos.y + 1), { playerStartPos: pv(this.path[this.path.length - 1].x, 0) });
            }
            master.exitData.screenShiftActive = true;
            master.exitData.movingTowardExit = true;
            return;
          }
        }

        this.pos.tweened = this.getTweenPos(this.path[0], this.path[1], this.timer);
        if (this.timer >= 1 && this.isIdle === false) {
          this.pos.current = this.path[1];
          this.pathHistory.push(this.path[0]);
          if (this.pathHistory.length > 3) {
            this.pathHistory.shift();
          }
          this.isIdle = true;
          this.animationFreeze.disableUserControl = false;
          this.pos.front = getFacingCell(this.playerFacingDir, this.pos.current);

          if (main.userControl === false) {
            if (R.next() > 0.8) {
              this.dig();
            }

            this.crouchAndPickup({ autonomous: true });
          }
        }
      }
    }
  }

  interpretUserControlKeyPress() {
    if (keyIsDown(UP_ARROW) || keyIsDown(87)) {
      if (!this.userControlQueue.includes("up")) {
        this.userControlQueue.unshift("up");
      }
    }
    if (keyIsDown(DOWN_ARROW) || keyIsDown(83)) {
      if (!this.userControlQueue.includes("down")) {
        this.userControlQueue.unshift("down");
      }
    }
    if (keyIsDown(LEFT_ARROW) || keyIsDown(65)) {
      if (!this.userControlQueue.includes("left")) {
        this.userControlQueue.unshift("left");
      }
    }
    if (keyIsDown(RIGHT_ARROW) || keyIsDown(68)) {
      if (!this.userControlQueue.includes("right")) {
        this.userControlQueue.unshift("right");
      }
    }
  }

  getTweenPos(current, next, timer) {
    let p1 = master.screen.getCellCoords(current);
    let p2 = master.screen.getCellCoords(next);

    return findPointAlongSpline([p1, p2], timer);
  }

  markTrail(tileType = 24) {
    master.screen.stampTileAtPos(this.pos.current, { tileType: tileType });
  }

  dig() {
    if (this.pos.front.x < 0 || this.pos.front.x >= world.screenSize[0] || this.pos.front.y < 0 || this.pos.front.y >= world.screenSize[1]) {
      return;
    } else if (master.screen.bin[this.pos.front.y][this.pos.front.x] === 111 || master.screen.bin[this.pos.front.y][this.pos.front.x] === 112 || master.screen.bin[this.pos.front.y][this.pos.front.x] === 113) {
      return;
    } else {
      player.showInventoryFull = false;
      if (this.animationFreeze.disableUserControl === false) {
        if (world.tileCodes.blocked.includes(master.screen.bin[this.pos.front.y][this.pos.front.x])) {
          this.noDiggingSound();
        } else {
          this.digSound();
        }

        this.animationFreeze.active = true;
        this.animationFreeze.type = "dig";
        this.animationFreeze.disableUserControl = true;
      }
    }
  }

  switchToUserControl() {
    main.userControl = true;
    this.userControlQueue = [];
    this.inactivityTimer = 0;
  }

  switchToAutoControl() {
    main.userControl = false;
    player.isIdle = true;
    main.showUserControlInfo = false;
    player.showInventoryFull = false;
    this.inactivityTimer = 0;
  }

  displayPlayer() {
    if (this.animationFreeze.active === false) {
      if (this.isIdle === true && this.userControlQueue.length <= 0) {
        let pos = master.screen.getCellCoords(this.pos.current);
        if (this.walkOnWater === true) {
