            sprites.sheet.animate(pos, { type: "raft" });
            pos.y -= 5 * master.screen.data.scalar;
            this.showingRaft = true;
          } else {
            this.showingRaft = false;
          }
        }
        if (this.playerFacingDir === -180) {
          sprites.sheet.animate(pos, { type: "idleUp" });
        } else if (this.playerFacingDir === -90) {
          sprites.sheet.animate(pos, { type: "idleRight" });
        } else if (this.playerFacingDir === 0) {
          sprites.sheet.animate(pos, { type: "idleDown" });
        } else if (this.playerFacingDir === 90) {
          sprites.sheet.animate(pos, { type: "idleLeft" });
