          fill(252, 217, 223);
          text("INVENTORY FULL", pos.x, pos.y - master.screen.data.cellSize * 0.5);
        }
      } else if (this.isIdle === true && this.userControlQueue.length > 0) {
        if (master.exitData.screenShiftActive === false) {
          let pos = master.screen.getCellCoords(this.pos.current);
          if (this.walkOnWater === true) {
            if (master.screen.bin[this.pos.current.y][this.pos.current.x] === 111 || master.screen.bin[this.pos.current.y][this.pos.current.x] === 112) {
              sprites.sheet.animate(pos, { type: "raft" });
              pos.y -= 5 * master.screen.data.scalar;
              this.showingRaft = true;
            } else {
              this.showingRaft = false;
            }
          }
          if (this.playerFacingDir === -180) {
            sprites.sheet.animate(pos, { type: "walkUp" });
          } else if (this.playerFacingDir === -90) {
            sprites.sheet.animate(pos, { type: "walkRight" });
          } else if (this.playerFacingDir === 0) {
            sprites.sheet.animate(pos, { type: "walkDown" });
          } else if (this.playerFacingDir === 90) {
            sprites.sheet.animate(pos, { type: "walkLeft" });
          }
          if (this.showInventoryFull === true) {
            noStroke();
            textSize(master.screen.data.scalar * 5);
            fill(199, 84, 103);
            text("INVENTORY FULL", pos.x + master.screen.data.scalar * 0.25, pos.y - master.screen.data.cellSize * 0.5 + master.screen.data.scalar * 0.25);
            fill(252, 217, 223);
            text("INVENTORY FULL", pos.x, pos.y - master.screen.data.cellSize * 0.5);
          }
        }
      } else if (this.isIdle === false) {
        if (master.exitData.screenShiftActive === false) {
          let pos = this.pos.tweened;
          if (this.walkOnWater === true) {
            if (master.screen.bin[this.pos.current.y][this.pos.current.x] === 111 || master.screen.bin[this.pos.current.y][this.pos.current.x] === 112) {
              sprites.sheet.animate(pos, { type: "raft" });
              pos.y -= 5 * master.screen.data.scalar;
              this.showingRaft = true;
            } else {
              this.showingRaft = false;
            }
          }
          if (this.playerFacingDir === -180) {
            sprites.sheet.animate(pos, { type: "walkUp" });
          } else if (this.playerFacingDir === -90) {
            sprites.sheet.animate(pos, { type: "walkRight" });
          } else if (this.playerFacingDir === 0) {
            sprites.sheet.animate(pos, { type: "walkDown" });
          } else if (this.playerFacingDir === 90) {
            sprites.sheet.animate(pos, { type: "walkLeft" });
          }
          if (this.showInventoryFull === true) {
            noStroke();
            textSize(master.screen.data.scalar * 5);
            fill(199, 84, 103);
            text("INVENTORY FULL", pos.x + master.screen.data.scalar * 0.25, pos.y - master.screen.data.cellSize * 0.5 + master.screen.data.scalar * 0.25);
            fill(252, 217, 223);
            text("INVENTORY FULL", pos.x, pos.y - master.screen.data.cellSize * 0.5);
          }
        }
      }
    } else {
      let prePos = this.pos.tweened !== false ? this.pos.tweened : master.screen.getCellCoords(this.pos.current);
      let pos = pv(prePos.x, prePos.y);
      if (this.walkOnWater === true) {
        if (master.screen.bin[this.pos.current.y][this.pos.current.x] === 111 || master.screen.bin[this.pos.current.y][this.pos.current.x] === 112) {
          sprites.sheet.animate(pos, { type: "raft" });
          pos.y -= 5 * master.screen.data.scalar;
          this.showingRaft = true;
