          this.showingRaft = false;
        }
      }
      if (this.animationFreeze.type === "crouch") {
        sprites.sheet.animate(pos, { type: "crouch" });
      } else if (this.animationFreeze.type === "show") {
        sprites.sheet.animate(pos, { type: "show" });
      } else if (this.animationFreeze.type === "dig") {
        let cloudPos = master.screen.getCellCoords(this.pos.front);

        if (this.playerFacingDir === -180) {
          sprites.sheet.animate(pos, { type: "shovelUp" });
          sprites.sheet.animate(pos, { type: "idleUp", bypassTimer: true });
          if (!world.tileCodes.blocked.includes(master.screen.bin[this.pos.front.y][this.pos.front.x])) {
            sprites.sheet.animate(cloudPos, { type: "dustCloud", bypassTimer: false });
          }
        } else if (this.playerFacingDir === -90) {
          sprites.sheet.animate(pos, { type: "idleRight", bypassTimer: true });
          sprites.sheet.animate(pos, { type: "shovelRight" });
          if (!world.tileCodes.blocked.includes(master.screen.bin[this.pos.front.y][this.pos.front.x])) {
            sprites.sheet.animate(cloudPos, { type: "dustCloud", bypassTimer: false });
          }
        } else if (this.playerFacingDir === 0) {
          sprites.sheet.animate(pos, { type: "idleDown", bypassTimer: true });
          sprites.sheet.animate(pos, { type: "shovelDown" });
          if (!world.tileCodes.blocked.includes(master.screen.bin[this.pos.front.y][this.pos.front.x])) {
            sprites.sheet.animate(cloudPos, { type: "dustCloud", bypassTimer: false });
          }
        } else if (this.playerFacingDir === 90) {
          sprites.sheet.animate(pos, { type: "idleLeft", bypassTimer: true });
          sprites.sheet.animate(pos, { type: "shovelLeft" });
          if (!world.tileCodes.blocked.includes(master.screen.bin[this.pos.front.y][this.pos.front.x])) {
            sprites.sheet.animate(cloudPos, { type: "dustCloud", bypassTimer: false });
          }
        }
      }
      this.animationFreeze.timer++;
      if (this.animationFreeze.timer > this.animationFreezeTimes[this.animationFreeze.type]) {
        sprites.sheet.resetTimer("dustCloud");

        let facingTileType;
        if (this.pos.front.y > world.screenSize[1] - 1 || this.pos.front.y < 0 || this.pos.front.x < 0 || this.pos.front.x > world.screenSize[0] - 1) {
          facingTileType = undefined;
        } else {
          facingTileType = master.screen.bin[this.pos.front.y][this.pos.front.x];
        }

        if (this.animationFreeze.type === "dig" && !world.tileCodes.blocked.includes(facingTileType) && facingTileType !== 1) {
          let stampPos;
          if (this.pos.tweened !== false && this.timer > 0.5) {
            stampPos = this.pos.front;
          } else if (this.pos.tweened !== false && this.timer <= 0.5) {
            stampPos = this.pos.current;
            stampPos = this.pos.front;
          } else {
            stampPos = this.pos.front;
          }
          let tileType = master.screen.bin[stampPos.y][stampPos.x];
          if (world.tileCodes.arrangeableItem.includes(tileType) || world.tileCodes.nonArrangeableItem.includes(tileType)) {
            let itemExists = false;
            this.itemBag.arrangeableItems.forEach((a) => {
              if (a.data.pos.x === stampPos.x && a.data.pos.y === stampPos.y && a.data.screenPos.x === master.screen.data.screenPos.x && a.data.screenPos.y === master.screen.data.screenPos.y) {
                itemExists = true;
              }
            });
            this.itemBag.cabinets.forEach((a) => {
              if (a.data.pos.x === stampPos.x && a.data.pos.y === stampPos.y && a.data.screenPos.x === master.screen.data.screenPos.x && a.data.screenPos.y === master.screen.data.screenPos.y) {
                itemExists = true;
              }
            });
            this.itemBag.orbs.forEach((a) => {
              if (a.data.pos.x === stampPos.x && a.data.pos.y === stampPos.y && a.data.screenPos.x === master.screen.data.screenPos.x && a.data.screenPos.y === master.screen.data.screenPos.y) {
                itemExists = true;
              }
            });

            if (itemExists === false) {
              let itemExistsOnScreen = false;
              master.screen.items.forEach((a) => {
                if (a.data.pos.x === stampPos.x && a.data.pos.y === stampPos.y && a.data.screenPos.x === master.screen.data.screenPos.x && a.data.screenPos.y === master.screen.data.screenPos.y) {
                  itemExistsOnScreen = true;
                }
              });
              if (itemExistsOnScreen === false) {
                master.screen.items.push(new ArrangeableItem({ tileType: tileType, arrangeable: true, pos: pv(stampPos.x, stampPos.y), screenPos: master.screen.data.screenPos }));
                if (tileType === 201 || tileType === 211) {
                  this.objectAppearsSoundAlternate();
                } else {
                  this.objectAppearsSound();
                }

                master.screen.items[master.screen.items.length - 1].drawToPg(master.screen.pgMid);
              }
            }
          } else {
          }

          if (world.tileCodes.nonArrangeableItem.includes(tileType)) {
            if (tileType === 201) {
              master.screen.stampFakeAtPos(stampPos, { tileType: 202 });
            } else if (tileType === 211) {
              master.screen.stampFakeAtPos(stampPos, { tileType: 212 });
            }
          } else {
            if (tileType >= 50 && tileType <= 59) {
              master.screen.stampFakeAtPos(stampPos, { tileType: tileType + 10 });
            } else if (tileType >= 80 && tileType <= 89) {
              master.screen.stampFakeAtPos(stampPos, { tileType: tileType - 20 });
            }
          }
        }
        this.animationFreeze.type = "";
        this.animationFreeze.active = false;
        this.animationFreeze.timer = 0;
        this.animationFreeze.disableUserControl = false;
      }
    }
  }
}

function getFacingCell(facingDir, currentPos) {
  if (facingDir === -180) {
    return pv(currentPos.x, currentPos.y - 1);
  } else if (facingDir === -90) {
    return pv(currentPos.x + 1, currentPos.y);
  } else if (facingDir === 0) {
    return pv(currentPos.x, currentPos.y + 1);
  } else if (facingDir === 90) {
    return pv(currentPos.x - 1, currentPos.y);
  }
  return currentPos;
}
class ArrangeableItem {
  constructor({ pos = pv(0, 0), screenPos = undefined, tileType = 80, bypassInfoSheet = false } = {}) {
    let seed = `${String(world.salt).substring(0, 4)}${screenPos.x}${screenPos.y}${pos.x}${pos.y}${String(world.salt).substring(0, 4)}`;
    this.data = { pos: pos, screenPos: screenPos, tileType: tileType, seed: seed, acquired: false, arrangeable: undefined, burn: undefined };
    this.data.hashString = reformatHashString(buildHashStringFromSeed(seed));
    this.R = new Random(this.data.hashString);

    if (world.tileCodes.arrangeableItem.includes(tileType)) {
      this.data.arrangeable = true;
      this.data.itemType = "rock";
      this.data.tileType = tileType;
      let easingStyle = 5;

      this.data.targetColor = determineRockColorBetter({ screenPos: screenPos, pos: pos, rng: this.R, easingStyle: easingStyle });
      this.data.targetTextString = determineRockStyle({ screenPos: screenPos, pos: pos,  rng:this.R});

      let sz = ratioDims(constrain(this.R.gaussian(0.5, 0.173), 0, 1), { range: [world.pixelsPerTile * 0.125, world.pixelsPerTile - world.pixelsPerTile * 0.125] });

      let szScalar = (world.pixelsPerTile - world.pixelsPerTile * 0.125) / Math.max(sz[0], sz[1]);
      sz[0] *= szScalar;
      sz[1] *= szScalar;

      this.item = new Rock(this.data.hashString, { targetColor: this.data.targetColor, targetTextString: this.data.targetTextString, sz: [Math.floor(sz[0]), Math.floor(sz[1])], bypassInfoSheet: bypassInfoSheet });

      this.itemData = this.item.getItemData();
    } else if (tileType === 201) {
      this.data.arrangeable = false;
      this.data.burn = false;
      this.data.tileType = tileType;
      this.data.itemType = "shelfBox";
      this.item = new ShelfBox2(this.data.hashString, { bypassInfoSheet: bypassInfoSheet });
      this.itemData = this.item.getItemData();
    } else if (tileType === 211) {
      this.data.arrangeable = false;
      this.data.burn = false;
      this.data.tileType = tileType;
      this.data.itemType = "orb";
      this.item = new Orb(this.data.hashString, { bypassInfoSheet: bypassInfoSheet });
      this.itemData = this.item.getItemData();
    }
  }

  displaySpriteAtPos({ pos = pv(0, 0) } = {}) {
    image(this.itemData.sprite, pos.x, pos.y, this.item.sz[0] * master.screen.data.scalar, this.item.sz[1] * master.screen.data.scalar);
  }

  pickupItem({ bypass = false } = {}) {
    this.data.acquired = true;
    master.screen.clearMidTileAtPos(this.data.pos);
    if (this.data.arrangeable === true) {
      player.itemBag.insertNextAvailable(this);
      main.textMessage = "NEW ROCK";

      if (bypass !== true) {
        player.itemPickupSound();
      }
    } else if (this.data.arrangeable === false) {
      if (this.data.itemType === "orb") {
        world.setWorldTile({ screenPos: this.data.screenPos, pos: this.data.pos, tileType: 212 });
        player.itemBag.orbs.push(this);
