function bandedPine({ density = 0.14, lines = 5, loops = 30 } = {}) {
  let crvs = [];

  for (let k = 0; k < lines; k++) {
    let wavyness = R.next(2, 5, true);
    if (R.next() > 0.2) {
      crvs.push(new Array(50).fill(0).map((a, iterA) => pv(iterA, R.next(-wavyness, wavyness))));
    } else {
      crvs.push(new Array(50).fill(0).map((a, iterA) => pv(iterA, R.next(-wavyness, wavyness) + mapQuadratic(iterA, 0, 50, 0, 1) * R.next(-10, 10))));
    }
  }

  for (let i = 0; i < crvs.length; i++) {
    crvs[i] = refitLineWithSetPoints(crvs[i], 100);
    soften(crvs[i], { loops: loops, start: 1, end: -1 });
  }

  for (let i = 1; i < crvs.length; i++) {
    let bbPrev = getBB(crvs[i - 1]);
    let bb = getBB(crvs[i]);
    translateArr(crvs[i], bb.p1, pv(bbPrev.p4.x, bbPrev.p4.y + R.next(30, 50)));
  }

  let bands = [];

  for (let i = 0; i < crvs.length - 1; i++) {
    let l1 = crvs[i];
    let l2 = crvs[i + 1];
    for (let j = 0; j < 0.95; j += density) {
      let band = [];
      for (let k = 0; k < l1.length; k++) {
        let newPt = pv(_lerp(l1[k].x, l2[k].x, j), _lerp(l1[k].y, l2[k].y, j));
        band.push(newPt);
      }

      bands.push(band);

      j += R.next(0, density * 0.5);
    }
  }

  for (let i = 0; i < bands.length; i++) {
    let bb = getBB(bands[i]);
    soften(bands[i], { loops: bb.height * 0.5, start: 1, end: -1 });
  }

  return bands;

  let bigBB = getBBC(bands);

  fill(166, 138, 86);
  drawBB(bigBB);
  noFill();
  blendMode(OVERLAY);
  bands.forEach((a, iterA) => {
    let val = noise(iterA * 0.5);
    if (val > 0.6 || val < 0.5) {
      val = easingFunction(val, 2) * 255;

      stroke(val, 50);
      let loops = R.next(1, 20, true);
      for (let k = 0; k < loops; k++) {
        drawArr(a, { pos: pv(0, R.next(-10, 10)) });
      }
    }
  });
}
