      pg.text(a, listPos.x, listPos.y + iterA * listScalar * 3);
    });

    let colorCard = makeRect(colorCardBB.mp, { sz: [colorCardBB.width * 0.95, colorCardBB.height * 0.8], closed: true });
    pg.fill(this.features.boxColor);
    pg_drawArr(colorCard, pg);
    pg.textAlign(CENTER, CENTER);
    pg.textSize(Math.min(colorCardBB.width, colorCardBB.height) * 0.1);
    if ((this.features.boxColor[0] + this.features.boxColor[1] + this.features.boxColor[2]) / 3 > 128) {
      pg.fill(0);
    } else {
      pg.fill(255);
    }
    pg.text(`Base Color\n rgb(${this.features.boxColor.slice(0, 3)})`, colorCardBB.mp.x, colorCardBB.mp.y);

    let styleDotsScalar = scalar * 0.1;
    let stylePos = pv(styleDotsBB.p4.x + styleDotsScalar * 0.9, styleDotsBB.p4.y - +styleDotsScalar * 0.9);
    let boxSize = Math.min(styleDotsBB.width, styleDotsBB.height) * 0.15;
    for (let i = 0; i < this.features.textString.length; i++) {
      pg.rectMode(CENTER);
      pg.fill(255);
      pg.rect(stylePos.x + i * boxSize * 1.1, stylePos.y, boxSize, boxSize);
      if (this.features.textString[i] === "1") {
        pg.fill(0);
        pg.circle(stylePos.x + i * boxSize * 1.1, stylePos.y, boxSize * 0.9);
        pg.fill(255);
      } else {
        pg.fill(255, 100);
      }
      pg.push();
      pg.textSize(scalar * 0.07);
      pg.textAlign(LEFT, CENTER);
      pg.translate(stylePos.x + i * boxSize * 1.1, stylePos.y - boxSize * 0.7);
      pg.rotate(radians(-90));
      pg.text(`${this.features.textureStyles[i]}`, 0, 0);
      pg.pop();
    }
    pg.remove();
    return pg;
  }

  displayInfoSheet(pos = pv(0, 0)) {
    image(this.infoSheet, pos.x, pos.y);
  }

  makeSprite() {
    let pg = createGraphics(this.sz[0], this.sz[1]);
    pg.remove();
    pg.pixelDensity(1);
    pg.noSmooth();
    pg.noStroke();
    let depthColor = [this.features.boxColor[0] - 50, this.features.boxColor[1] - 50, this.features.boxColor[2] - 50, 255];
    let faceColor;
    let multiColors = [];

    faceColor = [this.features.boxColor[0] + 50, this.features.boxColor[1] + 50, this.features.boxColor[2] + 50, 255];

    pg.fill(depthColor);
    pg.rect(9, 7, 16, 16);
    pg.rect(10, 6, 16, 16);
    if (this.features.shelfColorStyle === "same") {
      pg.fill(this.features.boxColor);
      pg.rect(8, 8, 16, 16);
    } else if (this.features.shelfColorStyle === "hue") {
      multiColors.push(this.features.boxColor, [this.features.boxColor[0] - 30, this.features.boxColor[1] + 30, this.features.boxColor[2] - 30, 255], [this.features.boxColor[0] + 30, this.features.boxColor[1] + 30, this.features.boxColor[2] - 30, 255], [this.features.boxColor[0] - 30, this.features.boxColor[1] + 30, this.features.boxColor[2] + 30, 255]);
      pg.fill(multiColors[0]);
      pg.rect(8, 8, 4, 10);
      pg.fill(multiColors[1]);
      pg.rect(8, 18, 4, 6);
      pg.fill(multiColors[2]);
      pg.rect(12, 8, 11, 4);
      pg.fill(multiColors[3]);
      pg.rect(12, 12, 11, 12);
    } else if (this.features.shelfColorStyle === "different") {
      multiColors.push([255, 0, 0, 255], [0, 100, 0, 255], [255, 220, 0, 255], [76, 150, 255, 255]);
      pg.fill(multiColors[0]);
      pg.rect(8, 8, 4, 10);
      pg.fill(multiColors[1]);
      pg.rect(8, 18, 4, 6);
      pg.fill(multiColors[2]);
      pg.rect(12, 8, 11, 4);
      pg.fill(multiColors[3]);
      pg.rect(12, 12, 11, 12);
    }

    pg.noFill();

    pg.stroke(faceColor);
    pg.line(12.5, 9, 12.5, 24);
    pg.line(8, 8.5, 23, 8.5);
    pg.line(8, 18.5, 12, 18.5);
    pg.line(12.5, 12.5, 23, 12.5);
    pg.line(23.5, 8.5, 23.5, 24);

    let textColor;
    if (this.features.shelfColorStyle === "same") {
      if ((this.features.boxColor[0] + this.features.boxColor[1] + this.features.boxColor[2]) / 3 > 255 / 2) {
        textColor = [50, 50, 50, 255];
      } else {
        textColor = [255, 255, 255, 255];
      }
    } else {
      textColor = [0, 0, 0, 255];
    }
    pg.fill(textColor);
    pg.noStroke();
    pg.textAlign(CENTER, CENTER);
    pg.textSize(12);

    pg.text(this.slotCount, pg.width / 2, pg.height / 2);
    pg.text(this.slotCount, pg.width / 2, pg.height / 2);
    pg.text(this.slotCount, pg.width / 2, pg.height / 2);
    pg = compressSingleFrame(pg, [this.features.boxColor, depthColor, faceColor, textColor, ...multiColors]);
    pg = outlineFrame(pg, { col: faceColor });

    return pg;
  }
}

class Orb {
  constructor(hashString, { bypassInfoSheet = false } = {}) {
    this.hashString = hashString;

    this.R = new Random(hashString);

    this.sz = [32, 32];
    this.targetBB = makeBBofSize(pv(this.sz[0] / 2, this.sz[1] / 2), { w: this.sz[0], h: this.sz[1] });
    this.features = this.generateFeatures();
    let spritePG = this.makeSprite();
    this.sprite = createGraphics(world.pixelsPerTile, world.pixelsPerTile);
    this.sprite.pixelDensity(1);
    this.sprite.noSmooth();
    this.sprite.noStroke();
    this.sprite.image(spritePG, 0, 0, world.pixelsPerTile - 0.5, world.pixelsPerTile - 0.5);
    this.sprite.remove();
    if (bypassInfoSheet === false) {
      this.infoSheet = this.generateInfoSheet();
    }
  }
  getItemData() {
    return { features: [], vectorData: [], sprite: this.sprite };
  }

  generateFeatures() {
    let features = {};

    features.colorStyle = this.R.choose(["coordinated", "coordinated", "different", "bwg", "bwg"]);
    features.wallStyle = this.R.choose(["argyle", "stripes", "falling stars", "diggly", "solid", "solid", "solid", "solid"]);
    features.floorStyle = this.R.choose(["wood", "tiles", "solid", "solid", "solid"]);

    if (features.colorStyle === "coordinated") {
      let col = [this.R.next(0, 360, true), 50, this.R.next(20, 80, true)];
      col = hslToRgb(col[0], col[1], col[2]);
      features.color = safeRGB(quantizeColors(col[0], col[1], col[2]));
      features.wallColorA = safeRGB(quantizeColors(features.color[0] + 50, features.color[1] + 50, features.color[2] + 50));
      features.floorColor = safeRGB(quantizeColors(features.color[0] - 50, features.color[1] - 50, features.color[2] - 50));
    } else if (features.colorStyle === "different") {
      let col = [this.R.next(0, 360, true), 50, this.R.next(20, 80, true)];
      col = hslToRgb(col[0], col[1], col[2]);
      features.color = safeRGB(quantizeColors(col[0], col[1], col[2]));
      col = complimentaryColor(features.color);
      features.wallColorA = safeRGB(quantizeColors(col[0], col[1], col[2]));
      features.floorColor = safeRGB(quantizeColors(features.color[0] + this.R.next(-50, -100), features.color[1] + this.R.next(-50, -100), features.color[2] + this.R.next(-50, -100)));
    } else if (features.colorStyle === "bwg") {
      let tone = this.R.choose([215, 20, this.R.next(50, 200, true), this.R.next(50, 200, true), this.R.next(50, 200, true)]);
      features.color = [tone, tone, tone, 255];
      features.wallColorA = safeRGB(quantizeColors(features.color[0] + 30, features.color[1] + 30, features.color[2] + 30));
      features.floorColor = safeRGB(quantizeColors(features.color[0] - 30, features.color[1] - 30, features.color[2] - 30));
    }

    features.wallColorB = safeRGB(quantizeColors(features.wallColorA[0] + this.R.next(-60, 60), features.wallColorA[1] + this.R.next(-60, 60), features.wallColorA[2] + this.R.next(-60, 60)));
    features.wallColorC = safeRGB(quantizeColors(features.wallColorA[0] + this.R.next(-60, 60), features.wallColorA[1] + this.R.next(-60, 60), features.wallColorA[2] + this.R.next(-60, 60)));

if (features.wallStyle === "falling stars") {
      features.wallColorA = safeRGB(quantizeColors(0, 0, 0));
      features.colorStyle = "n/a";
    }

    if (features.floorStyle === "wood") {
      features.floorColor = safeRGB(quantizeColors(150 + this.R.next(-60, 60), 111 + this.R.next(-60, 30), 51 + this.R.next(-60, 60)));
      features.colorStyle = "n/a";
    }
    features.woodHighlightColor = [features.floorColor[0] + 60, features.floorColor[1] + 60, features.floorColor[2] + 60, 255];
    features.tileDensity = 8;
    let pattern = "";
    for (let i = 0; i < 6; i++) {
      pattern += this.R.choose(["0", "1", "2"]);
    }
    if (!pattern.includes("1")) {
      pattern += "1";
    }
    if (!pattern.includes("2")) {
      pattern += "2";
    }
    if (!pattern.includes("0")) {
      pattern += "0";
    }
    features.stripesPattern = pattern + [...pattern].reverse().join("");
    features.argyleDensity = this.R.next(4, 12, true);
    features.distanceToWall = this.R.next(0.7, 0.97);
    return features;
  }

  generateInfoSheet() {
    let sz = [hud.infoBB.width, hud.infoBB.height];
    let pg = createGraphics(sz[0], sz[1]);
    pg.noSmooth();
    pg.noStroke();
    let scalar = Math.min(sz[1], sz[0]);
    let infoBB = makeBBofSize(pv(pg.width / 2, pg.height / 2), { w: pg.width, h: pg.height });
    let spriteSize = Math.min(pg.height, pg.width) * 0.45;
    let spriteBB = makeBBofSize(pv(spriteSize / 2, spriteSize / 2), { w: spriteSize, h: spriteSize });
    let titleHeight = pg.height * 0.1;
    let titleBB = makeBBofSize(pv(quickMp(spriteBB.p2, pv(pg.width, 0)).x, titleHeight * 0.5), { w: pg.width - spriteSize, h: titleHeight });
    let colorCardHeight = spriteSize - titleHeight;
    let colorCardBB = makeBBofSize(pv(quickMp(spriteBB.p2, pv(pg.width, 0)).x, titleBB.p3.y + colorCardHeight * 0.5), { w: pg.width - spriteSize, h: colorCardHeight });
    let styleDotsHeight = pg.height - spriteSize;
    let styleDotsWidth = pg.width * 0.6;
    let styleDotsBB = makeBBofSize(pv(0 + styleDotsWidth * 0.5, spriteBB.p3.y + styleDotsHeight * 0.5), { w: styleDotsWidth, h: styleDotsHeight });
    let listBB = makeBBofSize(pv(styleDotsBB.p2.x + (pg.width - styleDotsWidth) * 0.5, spriteBB.p3.y + styleDotsHeight * 0.5), { w: pg.width - styleDotsWidth, h: styleDotsHeight });

    pg.image(this.sprite, spriteBB.mp.x - spriteSize * 0.5, spriteBB.mp.y - spriteSize * 0.5, spriteSize, spriteSize);

    pg.fill(255);
    pg.textAlign(CENTER, CENTER);
    pg.textSize(Math.min(titleBB.width, titleBB.height) * 0.5);
    pg.text("BACKDROP", titleBB.mp.x, titleBB.mp.y);

    let list = [`color style:\n${this.features.colorStyle.toUpperCase()}`, `wall:\n${this.features.wallStyle.toUpperCase()}`, `floor:\n${this.features.floorStyle.toUpperCase()}`, `dist:\n${this.features.distanceToWall.toFixed(2)}`];

    pg.textAlign(CENTER, TOP);
    let listScalar = Math.min(listBB.width, listBB.height) * 0.08;
    pg.textSize(listScalar);
    pg.fill(255);

    let listPos = pv(listBB.mp.x, listBB.p2.y + listScalar * 0.5);
    list.forEach((a, iterA) => {
      pg.text(a, listPos.x, listPos.y + iterA * listScalar * 3);
    });

    let colorCardA = makeRect(pv(colorCardBB.mp.x, colorCardBB.mp.y - colorCardBB.height * 0.25), { sz: [colorCardBB.width * 0.95, colorCardBB.height * 0.5], closed: true });
    pg.fill(this.features.wallColorA);
    pg_drawArr(colorCardA, pg);
    pg.textAlign(CENTER, CENTER);
    pg.textSize(Math.min(colorCardBB.width, colorCardBB.height) * 0.1);
    if ((this.features.wallColorA[0] + this.features.wallColorA[1] + this.features.wallColorA[2]) / 3 > 128) {
      pg.fill(0);
    } else {
      pg.fill(255);
    }
    pg.text(`Wall Color\n rgb(${this.features.wallColorA.slice(0, 3)})`, colorCardBB.mp.x, colorCardBB.mp.y - colorCardBB.height * 0.25);
    let colorCardB = makeRect(pv(colorCardBB.mp.x, colorCardBB.mp.y + colorCardBB.height * 0.25), { sz: [colorCardBB.width * 0.95, colorCardBB.height * 0.5], closed: true });
    pg.fill(this.features.floorColor);
    pg_drawArr(colorCardB, pg);
    if ((this.features.floorColor[0] + this.features.floorColor[1] + this.features.floorColor[2]) / 3 > 128) {
      pg.fill(0);
    } else {
      pg.fill(255);
    }
    pg.text(`Floor Color\n rgb(${this.features.floorColor.slice(0, 3)})`, colorCardBB.mp.x, colorCardBB.mp.y + colorCardBB.height * 0.25);
    pg.remove();
    return pg;
  }

  displayInfoSheet(pos = pv(0, 0)) {
    image(this.infoSheet, pos.x, pos.y);
  }

  makeSprite() {
    let pg = createGraphics(this.sz[0], this.sz[1]);
    pg.remove();
    pg.pixelDensity(1);
    pg.noSmooth();
    pg.noStroke();

    pg.fill(this.features.wallColorA);
    pg.rect(6, 6, 20, 19);
    pg.fill(this.features.floorColor);
    pg.rect(6, 16, 20, 9);

    let floorLetter;
    if (this.features.floorStyle === "tiles") floorLetter = "T";
    else if (this.features.floorStyle === "wood") floorLetter = "W";
    else if (this.features.floorStyle === "solid") floorLetter = "";
    let wallLetter;
    if (this.features.wallStyle === "argyle") wallLetter = "A";
    else if (this.features.wallStyle === "stripes") wallLetter = "S";
    else if (this.features.wallStyle === "falling stars") wallLetter = "F";
    else if (this.features.wallStyle === "diggly") wallLetter = "D";
    else if (this.features.wallStyle === "solid") wallLetter = "";

    pg.textSize(10);

    for (let k = 0; k < 4; k++) {
      pg.textAlign(RIGHT, BOTTOM);
      if ((this.features.floorColor[0] + this.features.floorColor[1] + this.features.floorColor[2]) / 3 > 255 / 2) {
        pg.fill(0);
      } else {
        pg.fill(255);
      }
      pg.text(floorLetter, 24, 26);
      pg.textAlign(LEFT, TOP);
      if ((this.features.wallColorA[0] + this.features.wallColorA[1] + this.features.wallColorA[2]) / 3 > 255 / 2) {
        pg.fill(0);
      } else {
        pg.fill(255);
      }
      pg.text(wallLetter, 8, 7);
    }
    pg = compressSingleFrame(pg, [this.features.wallColorA, this.features.floorColor, [0, 0, 0, 255], [255, 255, 255, 255]]);
    pg = outlineFrame(pg, { col: [220, 220, 220, 255] });

    return pg;
  }
}

class Rock {
  constructor(hashString, { targetColor = undefined, targetTextString = "00000000", sz = [200, 200], bypassInfoSheet = false }) {
    this.hashString = hashString;
    this.R = new Random(this.hashString);
    this.sz = sz;
    this.targetBB = makeBBofSize(pv(sz[0] / 2, sz[1] / 2), { w: this.sz[0], h: this.sz[1] });

    this.rockTypes = [
      { weight: 100.0, fn: this.rockStyle_blobby.bind(this), name: "blobby" },
      { weight: 120.0, fn: this.rockStyle_multiRects.bind(this), name: "blobby" },
      { weight: 80.0, fn: this.rockStyle_twoRects.bind(this), name: "blobby" },
      { weight: 60.0, fn: this.rockStyle_bowl.bind(this), name: "boomerang" },
      { weight: 40.0, fn: this.rockStyle_comb.bind(this), name: "bone" },
      { weight: 60.0, fn: this.rockStyle_hole.bind(this), name: "hole" },
      { weight: 60.0, fn: this.rockStyle_binary.bind(this), name: "binary" },
      { weight: 25.0, fn: this.rockStyle_figure.bind(this), name: "figure" },
      { weight: 80.0, fn: this.rockStyle_riverStone.bind(this), name: "river" },
      { weight: 120.0, fn: this.rockStyle_mountain.bind(this), name: "mountain" },
      { weight: 100.0, fn: this.rockStyle_stack.bind(this), name: "stack" },
      { weight: 80.0, fn: this.rockStyle_angular.bind(this), name: "geometry" },
    ];
    this.totalWeight = this.rockTypes.reduce((sum, s) => sum + s.weight, 0);
    this.rockChoice = this.rouletteWheelSelection();

    this.features = this.determineFeatures(targetColor, targetTextString);

    this.vectorData = this.createVectorShape();
    this.sprite = this.createSprite();
    if (bypassInfoSheet === false) {
      this.infoSheet = this.generateInfoSheet();
    }
  }

  getItemData() {
    return { features: this.features, vectorData: this.vectorData, sprite: this.sprite };
  }

  determineFeatures(targetColor = [0, 0, 0, 255], targetTextString = "00000000") {
    this.features = {};
    this.features.fillColor = targetColor;
    this.features.outlineColor = safeRGB(quantizeColors(this.R.next(0, 255), this.R.next(0, 255), this.R.next(0, 255)));

    this.features.textureStyles = ["accents", "spots", "banded", "layers", "glossy", "textured", "flowers", "gradient"];

    this.features.textString = targetTextString;
    this.features.ratio = this.sz[0] / this.sz[1];
    this.features.rockType = this.rockChoice.name;
    this.features.accentChoice = this.R.choose(["first", "last", "both"]);
    return this.features;
  }

  generateInfoSheet() {
    let sz = [hud.infoBB.width, hud.infoBB.height];

    let pg = createGraphics(sz[0], sz[1]);
    pg.noSmooth();
    pg.noStroke();

    let scalar = Math.min(sz[1], sz[0]);
    let infoBB = makeBBofSize(pv(pg.width / 2, pg.height / 2), { w: pg.width, h: pg.height });
    let spriteSize = Math.min(pg.height, pg.width) * 0.45;
    let spriteBB = makeBBofSize(pv(spriteSize / 2, spriteSize / 2), { w: spriteSize, h: spriteSize });
    let titleHeight = pg.height * 0.1;
    let titleBB = makeBBofSize(pv(quickMp(spriteBB.p2, pv(pg.width, 0)).x, titleHeight * 0.5), { w: pg.width - spriteSize, h: titleHeight });
    let colorCardHeight = spriteSize - titleHeight;
    let colorCardBB = makeBBofSize(pv(quickMp(spriteBB.p2, pv(pg.width, 0)).x, titleBB.p3.y + colorCardHeight * 0.5), { w: pg.width - spriteSize, h: colorCardHeight });
    let styleDotsHeight = pg.height - spriteSize;
    let styleDotsWidth = pg.width * 0.6;
    let styleDotsBB = makeBBofSize(pv(0 + styleDotsWidth * 0.5, spriteBB.p3.y + styleDotsHeight * 0.5), { w: styleDotsWidth, h: styleDotsHeight });
    let listBB = makeBBofSize(pv(styleDotsBB.p2.x + (pg.width - styleDotsWidth) * 0.5, spriteBB.p3.y + styleDotsHeight * 0.5), { w: pg.width - styleDotsWidth, h: styleDotsHeight });

    let spriteScalar = spriteSize / Math.max(this.sprite.width, this.sprite.height);
    let adjustedSpriteSize = [this.sprite.width * spriteScalar, this.sprite.height * spriteScalar];
    pg.image(this.sprite, spriteBB.mp.x - adjustedSpriteSize[0] * 0.5, spriteBB.mp.y - adjustedSpriteSize[1] * 0.5, adjustedSpriteSize[0], adjustedSpriteSize[1]);

    pg.fill(255);
    pg.textAlign(CENTER, CENTER);
    pg.textSize(Math.min(titleBB.width, titleBB.height) * 0.5);
    pg.text("ROCK", titleBB.mp.x, titleBB.mp.y);

    let list = [`ratio:\n${this.features.ratio}`, `rock type:\n${this.features.rockType.toUpperCase()}`];

    pg.textAlign(CENTER, TOP);
    let listScalar = Math.min(listBB.width, listBB.height) * 0.08;
    pg.textSize(listScalar);
    pg.fill(255);

    let listPos = pv(listBB.mp.x, listBB.p2.y + listScalar * 0.5);
    list.forEach((a, iterA) => {
      pg.text(a, listPos.x, listPos.y + iterA * listScalar * 3);
    });

    let colorCard = makeRect(colorCardBB.mp, { sz: [colorCardBB.width * 0.95, colorCardBB.height * 0.8], closed: true });
    pg.fill(this.features.fillColor);
    pg_drawArr(colorCard, pg);
    pg.textAlign(CENTER, CENTER);
    pg.textSize(Math.min(colorCardBB.width, colorCardBB.height) * 0.1);
    if ((this.features.fillColor[0] + this.features.fillColor[1] + this.features.fillColor[2]) / 3 > 128) {
      pg.fill(0);
    } else {
      pg.fill(255);
    }
    pg.text(`Base Color\n rgb(${this.features.fillColor.slice(0, 3)})`, colorCardBB.mp.x, colorCardBB.mp.y);

    let styleDotsScalar = scalar * 0.1;
    let stylePos = pv(styleDotsBB.p4.x + styleDotsScalar * 0.9, styleDotsBB.p4.y - +styleDotsScalar * 0.9);
    let boxSize = Math.min(styleDotsBB.width, styleDotsBB.height) * 0.1;
    for (let i = 0; i < this.features.textString.length; i++) {
      pg.rectMode(CENTER);
      pg.fill(255);
      pg.rect(stylePos.x + i * boxSize * 1.1, stylePos.y, boxSize, boxSize);
      if (this.features.textString[i] === "1") {
        pg.fill(0);
        pg.circle(stylePos.x + i * boxSize * 1.1, stylePos.y, boxSize * 0.9);
        pg.fill(255);
      } else {
        pg.fill(255, 100);
      }
      pg.push();
      pg.textSize(scalar * 0.05);
      pg.textAlign(LEFT, CENTER);
      pg.translate(stylePos.x + i * boxSize * 1.1, stylePos.y - boxSize * 0.7);
      pg.rotate(radians(-90));
      pg.text(`${this.features.textureStyles[i]}`, 0, 0);
      pg.pop();
    }
    pg.remove();
    return pg;
  }

  displayInfoSheet(pos = pv(0, 0)) {
    image(this.infoSheet, pos.x, pos.y);
  }

  rockStyle_blobby() {
    let r1 = makeRect(pv(0, 0), { sz: [this.R.next(50, 100), this.R.next(50, 100)], closed: true });
    let r2;
    let joinCount = 0;
    let totalRounds = this.R.next(4, 80, true);

    let trim1;

    do {
      r2 = makeRect(findPointInShape(r1, { rng: this.R }), { sz: [this.R.next(50, 100), this.R.next(50, 100)], closed: true });
      if (curvesIntersect(r1, r2) === true) {
        trim1 = trimLineBy(r1, { knife: r2 });
        let trim2 = trimLineBy(r2, { knife: r1 });
        trim1 = [...trim1.outside, ...trim2.outside];
        trim1 = mendCurvesAlt(trim1);
        trim1.sort((a, b) => {
          return b.length - a.length;
        });
        r1 = trim1[0];
        joinCount++;
      }
    } while (joinCount < totalRounds);

    if (r1.length < 4) {
      r1 = createPointCircle(pv(0, 0), 200, 200, 8, true);
    }

    let longest = [0, 0];
    for (let i = 0; i < r1.length - 1; i++) {
      let qd = quickDist(r1[i], r1[i + 1]);
      if (qd > longest[0]) {
        longest[0] = qd;
        longest[1] = i;
      }
    }
    let ang = pointAng(r1[longest[1]], r1[longest[1] + 1]);
    let diff = findAngleBetween(ang, 90);
    let bb = getBB(r1);
    rotateShape(trim1, bb.mp, diff);

    r1 = refitLineWithSetSpacing(r1, 10);
    soften(r1, { loops: 20, start: -1, end: 1 });
    closeOpenShape(r1);
    r1 = trimBottom(r1);
    r1 = refitLineWithSetSpacing(r1, 10);
    soften(r1, { loops: 1, start: -1, end: 1 });
    closeOpenShape(r1);
    r1 = wind(r1, { dir: "clockwise" });

    let crv = r1;

    return [[crv], [], []];
  }

  rockStyle_multiRects() {
    let r1;
    let r2;

    r1 = makeRect(pv(0, 0), { sz: [this.R.next(50, 200), this.R.next(50, 100)], closed: true });
    r2 = makeRect(pv(0, 0), { sz: [this.R.next(50, 200), this.R.next(50, 100)], closed: true });
    translateArr(r1, quickMp(r1[0], r1[3]), pv(0, 0));
    translateArr(r2, quickMp(r2[0], r2[3]), pv(0, 0));

    rotateShape(r1, pv(0, 0), this.R.next(0, 360));
    rotateShape(r2, pv(0, 0), this.R.next(0, 360));

    let trim1 = trimLineBy(r1, { knife: r2 });
    let trim2 = trimLineBy(r2, { knife: r1 });
    trim1 = [...trim1.outside, ...trim2.outside];
    trim1 = mendCurvesAlt(trim1);
    r1 = trim1[0];
    let joinCount = 8;
    for (let i = 0; i < joinCount; i++) {
      let r3;
      r3 = makeRect(pv(0, 0), { sz: [this.R.next(100, 200), this.R.next(50, 100)], closed: true });
      translateArr(r3, quickMp(r3[0], r3[3]), pv(0, 0));
      rotateShape(r3, pv(0, 0), this.R.next(0, 360));
      if (curvesIntersect(r1, r3) === true) {
        trim1 = trimLineBy(r1, { knife: r3 });
        trim2 = trimLineBy(r3, { knife: r1 });
        trim1 = [...trim1.outside, ...trim2.outside];
        trim1 = mendCurvesAlt(trim1);
        trim1.sort((a, b) => {
          return b.length - a.length;
        });
        r1 = trim1[0];
      }
    }

    trim1 = r1;
    if (trim1.length < 4) {
      trim1 = createPointCircle(pv(0, 0), 200, 200, 8, true);
    }

    let longest = [0, 0];
    for (let i = 0; i < trim1.length - 1; i++) {
      let qd = quickDist(trim1[i], trim1[i + 1]);
      if (qd > longest[0]) {
        longest[0] = qd;
        longest[1] = i;
      }
    }
    let ang = pointAng(trim1[longest[1]], trim1[longest[1] + 1]);
    let diff = findAngleBetween(ang, 90);

    stroke(255, 255, 255);
    stroke(0);

    trim1 = refitLineWithSetSpacing(trim1, 10);
    soften(trim1, { loops: 20, start: -1, end: 1 });
    closeOpenShape(trim1);
    let bb = getBB(trim1);

    trim1 = trimBottom(trim1);
    trim1 = refitLineWithSetSpacing(trim1, 10);
    soften(trim1, { loops: 1, start: -1, end: 1 });
    closeOpenShape(trim1);
    trim1 = wind(trim1, { dir: "clockwise" });

    let crv = trim1;
    return [[crv], [], []];
  }

  rockStyle_twoRects() {
    let r1;
    let r2;

    do {
      r1 = makeRect(pv(this.R.next(-50, 50), this.R.next(-50, 50)), { sz: [this.R.next(10, 200), this.R.next(10, 200)], closed: true, rotationAmt: this.R.next(0, 360) });
      r2 = makeRect(pv(this.R.next(-50, 50), this.R.next(-50, 50)), { sz: [this.R.next(10, 200), this.R.next(10, 200)], closed: true, rotationAmt: this.R.next(0, 360) });
    } while (curvesIntersect(r1, r2) === false);

    let trim1 = trimLineBy(r1, { knife: r2 });
    let trim2 = trimLineBy(r2, { knife: r1 });

    trim1 = [...trim1.outside, ...trim2.outside];
    trim1 = mendCurvesAlt(trim1);
    trim1 = trim1[0];

    if (trim1.length < 4) {
      trim1 = createPointCircle(pv(0, 0), 200, 200, 8, true);
    }
    trim1 = refitLineWithSetSpacing(trim1, 10);
    soften(trim1, { loops: this.R.next(6, 6), start: -1, end: 1 });
    closeOpenShape(trim1);

    trim1 = trimBottom(trim1);
    soften(trim1, { loops: 2, start: -1, end: 1 });
    closeOpenShape(trim1);

    if (trim1.length <= 3) {
      trim1 = createPointCircle(pv(0, 0), 200, 200, 8, true);
    }

    let crv = trim1;
    return [[crv], [], []];
  }

  rockStyle_bowl() {
    let crv = makeRect(pv(0, 0), { sz: [200, 200], closed: true });
    let w = this.R.next(20, 60);
    let h = this.R.next(20, 60);
    crv.splice(1, 0, pv(-w, -100));
    crv.splice(2, 0, pv(-w, h));
    crv.splice(3, 0, pv(w, h));
    crv.splice(4, 0, pv(w, -100));
    crv = refitLineWithSetPoints(crv, 20);
    for (let i = 0; i < 10; i++) {
      scalePoint(crv[this.R.next(0, crv.length, true)], pv(0, 0), this.R.next(0.6, 1.1));
    }
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: 150, start: -1, end: 1 });
    closeOpenShape(crv);
    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);
    rotateShape(crv, pv(0, 0), this.R.choose([0, 0, 0, 180, 90, -90]));

    crv = trimBottom(crv);
    crv = refitLineWithSetSpacing(crv, 7);
    soften(crv, { loops: 1, start: -1, end: 1 });
    closeOpenShape(crv);

    return [[crv], [], []];
  }

  rockStyle_comb() {
    let crv = makeRect(pv(0, 0), { sz: [200, 200], closed: true });
    let comb = [];
    let span = this.R.choose([20, 25, 50]);
    let h = this.R.next(20, 80);
    let toothLength = this.R.next(50, 150);
    let diminishing = this.R.next(0.85, 1.3);
    for (let i = -100, count = 0; i <= 100 - span; i += span, count++) {
      if (count % 2 === 0) {
        comb.push(pv(i + span / 2, -toothLength));
        comb.push(pv(i + span / 2, h));
      } else {
        comb.push(pv(i + span / 2, h));
        comb.push(pv(i + span / 2, -toothLength));
      }
      if (diminishing < 1) {
        toothLength = toothLength * diminishing;
      }
    }

    comb[0].y = crv[0].y;
    comb[comb.length - 1].y = crv[1].y;
    if (diminishing < 1) {
      crv[1].y = comb[comb.length - 1].y;
    }
    crv.splice(1, 0, ...comb);
    if (this.R.next() > 0.5) {
      crv[crv.length - 4].x += this.R.next(0, 100);
      crv[crv.length - 3].x += this.R.next(0, 100);
      crv[crv.length - 2].x -= this.R.next(0, 100);
      crv[crv.length - 1].x -= this.R.next(0, 100);
    }
    if (this.R.next() > 0.5) {
      let clone = cloneArrRecursive(crv)[0];
      clone.reverse();

      scaleArrAxis(clone, pv(0, 0), -1, "y");
      translateArr(clone, pv(0, 0), pv(0, this.R.next(120, 200)));

      crv.splice(-3, 1, ...clone.slice(2));
      crv.splice(-2, 0, clone[0]);
    }

    crv = wind(crv, { dir: "counterClockwise" });

    if (this.sz[0] > this.sz[1]) {
      rotateShape(crv, pv(0, 0), this.R.choose([0, 180]));
    } else {
      rotateShape(crv, pv(0, 0), this.R.choose([-90, 90]));
    }

    if (this.R.next() > 0.5) {
      scaleArrAxis(crv, pv(0, 0), -1, "y");
    }
    closeOpenShape(crv);
    for (let i = 0; i < 10; i++) {
      scalePoint(crv[this.R.next(0, crv.length, true)], pv(0, 0), this.R.next(0.9, 1.1));
    }
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: this.R.next(50, 150), start: -1, end: 1 });
    closeOpenShape(crv);
    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);

    crv = trimBottom(crv);
    crv = refitLineWithSetSpacing(crv, 7);
    soften(crv, { loops: 2, start: -1, end: 1 });
    closeOpenShape(crv);

    return [[crv], [], []];
  }

  rockStyle_hole() {
    let crv = makeRect(pv(0, 0), { sz: [200, 200], closed: true });
    let holeSz = [this.R.next(50, 150), this.R.next(50, 150)];
    let holePos = pv(this.R.next(-10, 10), this.R.next(-10, 10));
    let hole = makeRect(holePos, { sz: holeSz, closed: true });
    crv = refitLineWithSetPoints(crv, 20);
    if (this.R.next() > 0.5) {
      for (let i = 0; i < 10; i++) {
        scalePoint(crv[this.R.next(0, crv.length, true)], pv(0, 0), this.R.next(1, 1.5));
      }
    }
    let bb = getBB(hole);
    if (this.R.next() > 0.5) {
      let fac = this.R.next(0, 1);
      scaleArrAxis(hole, holePos, 1 - 0.5 * fac, "x");
      translateArr(hole, pv(0, 0), pv(this.R.next(-bb.width * (0.25 * fac), bb.width * (0.25 * fac)), 0));
    } else {
      let fac = this.R.next(0, 1);
      scaleArrAxis(hole, holePos, 1 - 0.5 * fac, "y");
      translateArr(hole, pv(0, 0), pv(0, this.R.next(-bb.height * (0.25 * fac), bb.height * (0.25 * fac))));
    }
    hole = refitLineWithSetPoints(hole, 20);
    if (this.R.next() > 0.5) {
      for (let i = 0; i < 10; i++) {
        scalePoint(hole[this.R.next(0, hole.length, true)], pv(0, 0), this.R.next(0.6, 1));
      }
    }
    let loops = this.R.next(50, 350);
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: loops, start: -1, end: 1 });
    hole = refitLineWithSetSpacing(hole, 6);
    soften(hole, { loops: loops * 0.5, start: -1, end: 1 });
    closeOpenShape(crv);
    closeOpenShape(hole);
    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);

    crv = trimBottom(crv, { fac: 0.98 });
    crv = refitLineWithSetSpacing(crv, 7);
    soften(crv, { loops: 2, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [hole], []];
  }

  rockStyle_binary() {
    let mainW = this.R.next(10, 100);
    let span = this.R.next(1, 90);
    let heights = [this.R.next(100, 200), this.R.next(100, 200)];
    let crv = makeRect(pv(-mainW / 2 - span / 2, 0), { sz: [mainW, heights[0]], closed: true });
    let crv2 = makeRect(pv(mainW / 2 + span / 2, 0), { sz: [mainW, heights[1]], closed: true });
    let crv3 = makeRect(pv(0, this.R.next(-90, 90)), { sz: [span, 40], closed: true });
    crv.splice(2, 0, ...crv3.slice(0, 2));
    crv.splice(4, 0, ...crv2.slice(0, 4));
    crv.splice(8, 0, ...crv3.slice(2, 4));

    let rotation = this.R.choose([0, 90, 180, 360]);
    rotateShape(crv, pv(0, 0), rotation);

    crv = refitLineWithSetPoints(crv, 20);
    for (let i = 0; i < 10; i++) {
      scalePoint(crv[this.R.next(0, crv.length, true)], pv(0, 0), this.R.next(0.8, 1.1));
    }
    closeOpenShape(crv);
    let loops = this.R.next(10, 30);
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: loops, start: -2, end: 2 });
    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);

    crv = trimBottom(crv, { fac: 0.85 });
    crv = refitLineWithSetSpacing(crv, 2);
    soften(crv, { loops: 10, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [], []];
  }

  rockStyle_figure() {
    let mainW = this.R.next(90, 140);
    let span = this.R.next(10, 50);
    let neckGrth = this.R.next(10, 45);
    let headHt = this.R.next(80, 140);
    let headWdth = headHt * (this.sz[1] / this.sz[0]) * this.R.next(0.6, 0.9);
    let bodyW = 300;
    let crv = makeRect(pv(-mainW / 2 - span / 2, 0), { sz: [headHt, headWdth], closed: true });
    let crv2 = makeRect(pv(bodyW / 2 + span / 2, 0), { sz: [bodyW, 250], closed: true });
    let crv3 = makeRect(pv(0, 0), { sz: [span, neckGrth], closed: true });

    crv.splice(2, 0, ...crv3.slice(0, 2));
    crv.splice(4, 0, ...crv2.slice(0, 4));
    crv.splice(8, 0, ...crv3.slice(2, 4));
    crv = cloneArrRecursive(crv)[0];
    let ft = this.R.next(0, 90);
    crv[5].y += ft;
    crv[6].y -= ft;
    crv.splice(6, 0, pv(crv[5].x - this.R.next(bodyW * 0.4, bodyW * 0.4), 0));
    crv.splice(5, 0, pv(crv[4].x + bodyW * 0.2, crv[4].y));
    crv.splice(6, 0, pv(crv[5].x + bodyW * 0.1, crv[5].y + 100));
    crv.splice(7, 0, pv(crv[6].x + bodyW * 0.1, crv[5].y));

    crv.splice(11, 0, pv(crv[11].x + bodyW * 0.2, crv[11].y));
    crv.splice(11, 0, pv(crv[11].x + bodyW * 0.1, crv[11].y - 100));
    crv.splice(11, 0, pv(crv[11].x + bodyW * 0.1, crv[12].y));

    crv.splice(11, 0, crv2[2]);
    crv.splice(10, 0, pv(200, 75));

    crv.splice(8, 0, crv2[1]);
    crv.splice(10, 0, pv(200, -75));

    let thighs = this.R.next(0, 50);
    crv[7].y += thighs;
    crv[8].y += thighs;
    crv[9].y += thighs;

    crv[15].y -= thighs;
    crv[14].y -= thighs;
    crv[13].y -= thighs;

    crv[10].y = (crv[8].y + crv[11].y) / 2;
    crv[12].y = (crv[11].y + crv[14].y) / 2;

    let arms = this.R.next(0, 100);
    crv.splice(6, 0, pv(crv[6].x - arms, crv[6].y));
    crv.splice(18, 0, pv(crv[17].x - arms, crv[17].y));

    rotateShape(crv, pv(0, 0), 90);

    shiftArrayIndexes(crv, this.R.next(0, crv.length, true));
    closeOpenShape(crv);

    for (let i = 0; i < 10; i++) {
      scalePoint(crv[this.R.next(0, crv.length, true)], pv(0, 0), this.R.next(0.98, 1.02));
    }
    closeOpenShape(crv);
    let loops = 50;
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: loops, start: -1, end: 1 });

    closeOpenShape(crv);

    crv = trimBottom(crv, { fac: 0.95 });
    crv = refitLineWithSetSpacing(crv, 2);
    soften(crv, { loops: 10, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [], []];
  }

  rockStyle_riverStone() {
    let crv = makeRect(pv(0, 0), { sz: [200, 200], closed: true });
    crv = refitLineWithSetPoints(crv, 20);
    for (let i = 0; i < 10; i++) {
      scalePoint(crv[this.R.next(0, crv.length, true)], pv(0, 0), this.R.next(0.7, 1.1));
    }
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: this.R.next(10, 150, true), start: -1, end: 1 });
    closeOpenShape(crv);
    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [], []];
  }

  rockStyle_mountain() {
    let crv = [pv(this.R.next(-150, -100), 0)];
    for (let i = -100; i < 100; i += 10) {
      crv.push(pv(i, this.R.next(-100, -20)));
    }
    crv.push(pv(this.R.next(100, 150), 0));
    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: this.R.next(30, 30, true), start: 1, end: -1 });
    closeOpenShape(crv);

    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [], []];
  }

  rockStyle_stack() {
    let rects = [];
    let count = this.R.next(5, 10, true);
    let maxWidth = this.R.next(150, 800, true);

    for (let i = 0; i < count; i++) {
      if (rects.length <= 0) {
        rects.push(makeRect(pv(0, 0), { sz: [this.R.next(100, maxWidth), this.R.next(50, 100)], closed: true }));
      }
      rects.push(makeRect(pv(this.R.next(rects[rects.length - 1][0].x, rects[rects.length - 1][1].x), rects[rects.length - 1][0].y), { sz: [this.R.next(100, maxWidth), this.R.next(50, 100)], closed: true }));
    }

    let crv = rects.splice(0, 1)[0];

    for (let i = 0; i < rects.length; i++) {
      if (curvesIntersect(crv, rects[i]) === true) {
        let trim1 = trimLineBy(crv, { knife: rects[i] });
        let trim2 = trimLineBy(rects[i], { knife: crv });
        trim1 = [...trim1.outside, ...trim2.outside];
        trim1 = mendCurvesAlt(trim1);
        crv = trim1[0];
      } else if (shapeInsideShape(crv, rects[i]) === true) {
        crv = rects[i];
      }
    }

    if (crv.length < 4) {
      crv = createPointCircle(pv(0, 0), 200, 200, 8, true);
    }

    crv = refitLineWithSetSpacing(crv, 6);
    soften(crv, { loops: this.R.next(50, 150), start: -1, end: 1 });
    closeOpenShape(crv);
    crv = refitLineWithSetSpacing(crv, 1);
    soften(crv, { loops: 50, start: -1, end: 1 });
    closeOpenShape(crv);

    crv = trimBottom(crv, { fac: 0.95 });
    crv = refitLineWithSetSpacing(crv, 2);
    soften(crv, { loops: 10, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [], []];
  }

  rockStyle_angular() {
    let ang = this.R.next();
    if (ang > 0.3) {
      ang = this.R.next(45, 121, true);
    } else {
      ang = this.R.choose([45, 51.43, 60, 72, 90, 120]);
    }

    let crv = createPointCircle(pv(0, 0), 100, 100, ang, true);
    ang = pointAng(crv[0], crv[1]);
    ang = findAngleBetween(ang, -90);
    rotateShape(crv, pv(0, 0), ang);

    if (this.R.next() > 0.5) {
      scaleArrAxis(crv, pv(0, 0), -1, "x");
    }

    if (this.R.next() > 0.5) {
      rotateShape(crv, pv(0, 0), this.R.choose([-90, 90, 180]));
    }
    crv = wind(crv, { dir: "clockwise" });

    closeOpenShape(crv);
    crv = refitLineWithSetSpacing(crv, 3);
    soften(crv, { loops: this.R.next(10, 50, true), start: -1, end: 1 });
    closeOpenShape(crv);

    crv = trimBottom(crv, { fac: 0.91 });
    crv = refitLineWithSetSpacing(crv, 2);
    soften(crv, { loops: 4, start: -1, end: 1 });
    closeOpenShape(crv);
    return [[crv], [], []];
  }

  rouletteWheelSelection() {
    const choice = this.R.next(0, this.totalWeight);

    let accumulator = 0;
    for (const a of this.rockTypes) {
      accumulator += a.weight;

      if (choice <= accumulator) {
        return a;
      }
    }
  }

  createVectorShape() {
    let data = this.rockChoice.fn();
    let vectorData = [];
    vectorData.push({ arr: data[0] });
    vectorData.push({ arr: data[1] });
    vectorData.push({ arr: data[2] });

    let bb = [];
    vectorData.forEach((a) => {
      bb.push(getBBC(a.arr));
    });
    bb = combineBB(bb);

    let scalarX = getScalar(bb.p1, bb.p2, pv(0, 0), pv(this.sz[0], 0)) * 0.9;
    let scalarY = getScalar(bb.p1, bb.p4, pv(0, 0), pv(0, this.sz[1])) * 0.9;
    vectorData.forEach((a, iterA) => {
      a.arr.forEach((b, iterB) => {
        scaleArrAxis(b, bb.mp, scalarX, "x");
        scaleArrAxis(b, bb.mp, scalarY, "y");
        translateArr(b, bb.mp, this.targetBB.mp);

        closeOpenShape(b);
      });
    });

    let issueFound = false;
    vectorData.forEach((a) => {
      a.arr.forEach((b) => {
        b.forEach((c) => {
          if (isNaN(c.x) || isNaN(c.y)) {
            issueFound = true;
          }
        });
      });
    });

    if (issueFound === true) {
      vectorData[0].arr = [makeRect(this.targetBB.mp, { sz: this.sz, closed: true })];
      vectorData[0].arr[0] = refitLineWithSetPoints(vectorData[0].arr[0], 50);
      soften(vectorData[0].arr[0], { loops: 50, start: -1, end: 1 });
      closeOpenShape(vectorData[0].arr[0]);
    }

    return vectorData;
  }

  createSprite() {
    let pg = this.processTexture({ pixelSize: true });

    pg = compressSingleFrame(pg);
    pg = pgRemoveBottomRows(pg);

    pg.remove();
    return pg;
  }

  displayVector(scalar, { useOutlines = false, shelfBoxColor = undefined } = {}) {
    this.processTexture({ pixelSize: false });

    if (useOutlines === true) {
      if ((shelfBoxColor[0] + shelfBoxColor[1] + shelfBoxColor[2]) / 3 > 128) {
        stroke(0);
      } else {
        stroke(255);
      }
      noFill();
      this.vectorData.forEach((a) => {
        a.arr.forEach((b) => {
          drawArr(b);
        });
      });
    }
  }

  processTexture({ pixelSize = true } = {}) {
    let bb = [];
    this.vectorData.forEach((a) => {
      bb.push(getBBC(a.arr));
    });
    bb = combineBB(bb);

    let padding = Math.round(Math.min(bb.width, bb.height) * 0.01);
    let offset = pv(-bb.p1.x + padding / 2, -bb.p1.y + padding / 2);
    let pg = createGraphics(Math.round(bb.width) + padding, Math.round(bb.height) + padding);

    pg.noSmooth();
    let polkadots = this.textureMap(this.vectorData[0].arr, this.vectorData[1].arr, this.vectorData[2].arr, { offset: offset, bb: bb, padding: padding, pixelSize: pixelSize });
    polkadots = cookieCutterWithHoles(this.vectorData[0].arr, this.vectorData[1].arr, polkadots, { offset: offset });
    pg.image(polkadots, 0, 0);
    pg.remove();
    noStroke();
    if (pixelSize === true) {
      return pg;
    } else {
      offset = pv(-bb.p1.x + padding / 2, -bb.p1.y + padding / 2);
      image(pg, bb.p1.x - padding / 2, bb.p1.y - padding / 2);
    }

    return pg;
  }

  textureMap(shapes, holes, details, { offset = pv(0, 0), bb = undefined, padding = undefined, pixelSize = true } = {}) {
    let scalar = Math.min(bb.width, bb.height) / 50;
    let R = new Random(this.hashString);
    let pd = pixelDensity();
    let pg = createGraphics(bb.width * pd + padding, bb.height * pd + padding);
    let colorAve = (this.features.fillColor[0] + this.features.fillColor[1] + this.features.fillColor[2]) / 3;
    let colorTone;
    if (this.features.fillColor[0] <= 40 && this.features.fillColor[1] <= 40 && this.features.fillColor[2] <= 40) {
      colorTone = "dark";
    } else if (this.features.fillColor[0] >= 220 && this.features.fillColor[1] >= 220 && this.features.fillColor[2] >= 220) {
      colorTone = "light";
    } else {
      colorTone = "medium";
    }
    pg.remove();
    pg.pixelDensity(pd);
    pg.background(0);
    pg.noStroke();
    pg.fill(255, 4);
    let shadeRange = 8;
    for (let i = 0; i < 80; i++) {
      pg_drawArr(shapes[0], pg, { pos: pv(offset.x + R.next(-scalar * shadeRange, scalar * shadeRange), offset.y - scalar * 1 + R.next(-scalar * shadeRange, scalar * 2)) });
      if (holes.length > 0) {
        pg_drawArr(holes[0], pg, { pos: pv(offset.x + R.next(-scalar * shadeRange, scalar * shadeRange), offset.y - scalar * 1 + R.next(-scalar * shadeRange, scalar * 2)) });
      }
    }

    pg.fill(this.features.fillColor);
    pg.blendMode(MULTIPLY);
    pg.rect(0, 0, pg.width, pg.height);
    pg.blendMode(SCREEN);
    pg.rect(0, 0, pg.width, pg.height);
    pg.blendMode(BLEND);
    let cpy = pg.get();
    for (let i = 0; i < 4; i++) {
      pg.blendMode(MULTIPLY);
      pg.image(cpy, 0, 0);
      pg.blendMode(SCREEN);
      pg.image(cpy, 0, 0);
      pg.blendMode(MULTIPLY);
      pg.image(cpy, 0, 0);
    }
if (this.features.textString[0] === "1") {
      if (this.features.accentChoice === "first" || this.features.accentChoice === "both") {
        R = new Random(this.hashString);
        pg.blendMode(BLEND);
        let sz = ratioDims(constrain(R.gaussian(0.5, 0.15), 0, 1), { range: [scalar * 4, scalar * 20] });
        let c = createPointCircle(pv(0, 0), sz[0], sz[1], 3, true, { rotationAmt: R.next(0, 360) });
        for (let i = 0; i < 20; i++) {
          scalePoint(c[R.next(0, c.length, true)], pv(0, 0), R.next(0.5, 1.5));
        }
        c = refitLineWithSetPoints(c, Math.floor(360 / 3));
        soften(c, { loops: 30, start: -1, end: 1 });
        scaleArr(c, pv(0, 0), R.next(0.8, 1.8));
        let compColor = complimentaryColor(this.features.fillColor);
        compColor = safeRGB(quantizeColors(compColor[0] + R.next(-60, 60), compColor[1] + R.next(-60, 60), compColor[2] + R.next(-60, 60), { step: 15, max: 255 }));
        pg.fill(...compColor.slice(0, 3), R.next(10, 65, true));
        pg.noStroke();
        for (let k = 0; k < 3; k++) {
          let pt = findPointInShape(shapes[0], { rng: R });
          let rounds = R.next(1, 30, true);
          for (let p = 0; p < rounds; p++) {
            pg_drawArr(c, pg, { pos: pv(offset.x + pt.x + R.next(-scalar * 3, scalar * 3), offset.y + pt.y + R.next(-scalar * 3, scalar * 3)) });
          }
          scaleArr(c, pv(0, 0), R.next(0.8, 1.8));
        }
        pg.noFill();
      }
    }
    if (this.features.textString[7] === "1") {
      pg.blendMode(BLEND);
      let gradColor = safeRGB(quantizeColors(R.next(0, 255), R.next(0, 255), R.next(0, 255), { step: 15, max: 255 }));
      let rotStyle = R.choose(["cardinal", "random"]);
      let graAng = rotStyle === "cardinal" ? 0 : R.next(0, 360);
      let easingStyle = 5;
      for (let k = 0; k < 3; k++) {
        let squareSz = quickDist(pv(0, 0), pv(pg.width / pd / 2, pg.height / pd / 2));
        let interval = scalar * 0.1;
        pg.strokeWeight(scalar * 0.1);
        pg.push();
        pg.translate(pg.width / pd / 2, pg.height / pd / 2);
        let gradAngMixer = R.next(10, 45);
        let rotAng = graAng + R.next(-gradAngMixer, gradAngMixer);
        pg.rotate(radians(rotAng));
        for (let j = -squareSz; j < squareSz; j += interval) {
          let val = _map(j, -squareSz, squareSz, 0, 1);
          val = easingFunction(val, easingStyle);
          val = map(val, 0, 1, 180, 0);
          pg.stroke(...gradColor.slice(0, 3), val);
          pg.line(-squareSz, j, squareSz, j);
        }
        pg.pop();
      }
    }

    if (this.features.textString[0] === "1") {
      if (this.features.accentChoice === "last" || this.accentChoice === "both") {
        R = new Random(this.hashString);
        R.purge(1000);
        pg.blendMode(BLEND);
        let rg = R.gaussian(0.5, 0.15);
        let sz = ratioDims(constrain(rg, 0, 1), { range: [scalar * 4, scalar * 10] });
        let c = createPointCircle(pv(0, 0), sz[0], sz[1], 20, true, { rotationAmt: R.next(0, 360) });
        let spikeFac = R.next(0.5, 0.8);
        let spikeRounds = R.next(10, 200, true);
        for (let i = 0; i < spikeRounds; i++) {
          scalePoint(c[R.next(0, c.length, true)], pv(0, 0), R.next(1 - spikeFac, 1 + spikeFac));
        }
        let compColor = [...this.features.fillColor];
        if (R.next() > 0.5) {
          compColor = safeRGB(quantizeColors(compColor[0] + R.next(-160, 160), compColor[1] + R.next(-160, 160), compColor[2] + R.next(-160, 160), { step: 15, max: 255 }));
        } else {
          compColor = safeRGB(quantizeColors(compColor[0] + R.next(-60, 60), compColor[1] + R.next(-60, 60), compColor[2] + R.next(-60, 60), { step: 15, max: 255 }));
        }
        pg.fill(...compColor.slice(0, 3), 15, R.next(10, 85, true));
        pg.noStroke();
        for (let k = 0; k < 3; k++) {
          let pt = findPointInShape(shapes[0], { rng: R });
          let rounds = 50;
          for (let p = 0; p < rounds; p++) {
            let rotAmt = R.next(0, 360);
            rotateShape(c, pv(0, 0), rotAmt);
            pg_drawArr(c, pg, { pos: pv(offset.x + pt.x + R.next(-scalar * 4, scalar * 4), offset.y + pt.y + R.next(-scalar * 4, scalar * 4)) });
          }
          scaleArr(c, pv(0, 0), R.next(0.8, 1.8));
        }
        pg.noFill();
      }
    }

    if (this.features.textString[1] === "1") {
      R = new Random(this.hashString);

      pg.noStroke();
      pg.blendMode(BLEND);
      let spotCount = R.next(30, 100, true);

      let spotSize = R.choose(["varied", R.next(1, 3)]);

      let spots = new Array(spotCount).fill(0).map(() => [pv(R.next(0, 1), R.next(0, 1)), spotSize === "varied" ? R.next(1, 3) : spotSize, R.next(0.5, 3)]);

      let spotColor;
      if (colorTone === "dark") {
        spotColor = safeRGB([this.features.fillColor[0] + R.next(20, 200), this.features.fillColor[1] + R.next(20, 200), this.features.fillColor[2] + R.next(20, 200), 255]);
      } else if (colorTone === "bright") {
        spotColor = safeRGB([this.features.fillColor[0] + R.next(-20, -200), this.features.fillColor[1] + R.next(-20, -200), this.features.fillColor[2] + R.next(-20, -200), 255]);
      } else {
        spotColor = safeRGB([this.features.fillColor[0] + R.next(-100, 100), this.features.fillColor[1] + R.next(-100, 100), this.features.fillColor[2] + R.next(-100, 100), 255]);
      }

      let spotColorRainbow = R.next() > 0.68 ? true : false;

      for (let i = 0; i < spots.length; i++) {
        let rounds = R.next(10, 80, true);
        let opacity = _map(rounds, 10, 80, 60, 10);
        let sharpness = R.next(0.005, 0.02);
        if (spotColorRainbow) {
          if (colorTone === "dark") {
            spotColor = safeRGB([this.features.fillColor[0] + R.next(20, 200), this.features.fillColor[1] + R.next(20, 200), this.features.fillColor[2] + R.next(20, 200), 255]);
          } else if (colorTone === "bright") {
            spotColor = safeRGB([this.features.fillColor[0] + R.next(-20, -200), this.features.fillColor[1] + R.next(-20, -200), this.features.fillColor[2] + R.next(-20, -200), 255]);
          } else {
            spotColor = safeRGB([this.features.fillColor[0] + R.next(-100, 100), this.features.fillColor[1] + R.next(-100, 100), this.features.fillColor[2] + R.next(-100, 100), 255]);
          }
        }
        pg.fill(...spotColor.slice(0, 3), opacity);

        for (let k = 0; k < rounds; k++) {
          let mapped = _map(k, 0, rounds, 0, 1);
          mapped = easingFunction(mapped, 3);
          let circlePos = pv((spots[i][0].x + R.next(-sharpness, sharpness)) * (pg.width / pd), (spots[i][0].y + R.next(-sharpness, sharpness)) * (pg.height / pd));
          let circleSize = spots[i][1] * scalar * mapped * 4;

          pg.circle(circlePos.x, circlePos.y, circleSize);
        }
      }
      pg.noFill();
      pg.blendMode(BLEND);
    }

    if (this.features.textString[2] === "1") {
      R = new Random(this.hashString);

      pg.noFill();
      let sz = [R.next(1, 1.1), R.next(0.1, 0.5)];
      let ln = createPointCircle(pv(0, 0), sz[0] * (pg.width / pd), sz[1] * (pg.height / pd), 10, false, { start: 270, end: 270 + 180, rotationAmt: R.next(0, 360) });
      for (let i = 0; i < 15; i++) {
        let pt = ln[R.next(1, ln.length - 1, true)];
        scalePoint(pt, pv(0, 0), R.next(0.8, 1.2));
      }

      ln = refitLineWithSetPoints(ln, 400);

      soften(ln, { loops: R.next(10, 100, true), start: 1, end: -1 });

      translateArr(ln, pv(ln[Math.floor(ln.length / 2)].x, ln[Math.floor(ln.length / 2)].y), pv(pg.width / pd / 2, pg.height / pd / 2));
      if (colorTone === "dark") {
        pg.blendMode(DODGE);
      } else {
        pg.blendMode(OVERLAY);
      }
      let col = [];
      if (colorAve < 188) {
        col = [205, 205, 205, R.next(50, 50)];
      } else {
        col = [50, 50, 50, R.next(50, 100)];
      }
      if (R.next() > 0.45) {
        blendMode(BLEND);
        col = [R.next(50, 180), R.next(50, 180), R.next(50, 180), R.next(50, 100)];
      }
      let lnCount = R.next(1, 5, true);
      pg.fill(col);
      let bandWeight = R.next(6, 12, true);
      for (let i = 0; i < lnCount; i++) {
        pg.strokeWeight(scalar * 0.4);
        pg.noStroke();
        let offsetLn = pv(R.next(-1, 1), R.next(-1, 1));
        offsetLn = pv(offsetLn.x * scalar * (4 + lnCount), offsetLn.y * scalar * (4 + lnCount));
        ln.forEach((a, iterA) => {
          let mapped = _map(iterA, 0, ln.length, 0, 1);
          mapped = mapQuadratic(mapped, 0, 1, 0.2, 0.6);
          let extraPush = pv(R.next(-0.5, 0.5), R.next(-0.5, 0.5));
          pg.circle(a.x + offsetLn.x + extraPush.x * scalar, a.y + offsetLn.y + extraPush.y * scalar, scalar * mapped * bandWeight);
        });
      }
    }

    if (this.features.textString[3] === "1") {
      R = new Random(this.hashString);

      if (colorTone === "dark") {
        pg.blendMode(SOFT_LIGHT);
      } else {
        pg.blendMode(OVERLAY);
      }
      let diag = quickDist(pv(0, 0), pv(pg.width / pd / 2, pg.height / pd / 2));
      let extents = [pointFrom(pv(pg.width / pd / 2, pg.height / pd / 2), 180, diag), pointFrom(pv(pg.width / pd / 2, pg.height / pd / 2), 0, diag)];
      let wavyness = R.next(2, 5, true);
      let bow = R.next(0, 12, true);
      let ln1 = new Array(50).fill(0).map((a, iterA) => pv(iterA, R.next(-wavyness, wavyness) + mapQuadratic(iterA, 0, 50, 0, 1) * bow));
      let ln2 = new Array(50).fill(0).map((a, iterA) => pv(iterA, R.next(-wavyness, wavyness) + mapQuadratic(iterA, 0, 50, 0, 1) * bow));
      ln1 = refitLineWithSetPoints(ln1, 150);
      ln2 = refitLineWithSetPoints(ln2, 150);
      soften(ln1, { loops: 8, start: 1, end: -1 });
      soften(ln2, { loops: 8, start: 1, end: -1 });
      let rotAmt = R.next(0, 360);

      translateArr(ln1, pv(25, 0), extents[0]);
      scaleArr(ln1, extents[0], (diag * 2) / 50);
      rotateShape(ln1, pv(pg.width / pd / 2, pg.height / pd / 2), rotAmt);

      translateArr(ln2, pv(25, 0), extents[1]);
      scaleArr(ln2, extents[1], (diag * 2) / 50);
      rotateShape(ln2, pv(pg.width / pd / 2, pg.height / pd / 2), rotAmt);

      let layers = [];
      let increment = R.next(0.008, 0.04);

      let rFactor = 0.2;
      for (let j = 0; j < 1; j += increment) {
        let layer = [];
        for (let i = 0; i < ln1.length; i++) {
          layer.push(pv(_lerp(ln1[i].x, ln2[i].x, j + R.next(-increment * rFactor, increment * rFactor)), _lerp(ln1[i].y, ln2[i].y, j + R.next(-increment * rFactor, increment * rFactor))));
        }
        soften(layer, { loops: R.next(1, 28, true), start: 1, end: -1 });
        layers.push(layer);
        j += R.next(0, increment * 4);
      }

      let strats = [];
      for (let i = 0; i < layers.length - 1; i++) {
        let strat = [];
        strat.push(...layers[i]);
        strat.push(...cloneArrRecursive(layers[i + 1])[0].reverse());
        strats.push(strat);
      }

      pg.noStroke();

      let colorStyle = R.choose(["alternating", "random", "graded"]);

      let opacity = R.next(40, 255, true);
      strats.forEach((a, iterA) => {
        let col;
        if (colorStyle === "random") {
          col = [...safeRGB(quantizeColors(R.next(0, 255), R.next(0, 255), R.next(0, 255))).slice(0, 3), opacity];
        } else if (colorStyle === "alternating") {
          iterA % 2 === 0 ? (col = [...this.features.fillColor.slice(0, 3), opacity]) : (col = [255, 255, 255, opacity]);
        } else if (colorStyle === "graded") {
          col = [(iterA * 255) / strats.length + R.next(-20, 20), (iterA * 255) / strats.length + R.next(-20, 20), (iterA * 255) / strats.length + R.next(-20, 20), 200];
        }

        pg.fill(col);
        pg_drawArr(a, pg, { pos: pv(0, 0) });
      });
    }

    if (this.features.textString[4] === "1") {
      pg.blendMode(BLEND);
      pg.strokeWeight(scalar * 10);
      pg.stroke(0);

      let gloss = extractGloss(shapes[0], { dir: -90, range: 30 });
      pg.noStroke();
      pg.fill(255, 150);
      gloss.forEach((a) => {
        if (a.length > 2) {
          let increment = (0.5 / splineDist(a)) * scalar;
          for (let p = 0; p <= 1; p += increment) {
            let pt = findPointAlongSpline(a, p);
            let mapped = mapQuadratic(p, 0, 1, 1, 2);
            pg.circle(offset.x + pt.x, offset.y + pt.y + scalar * 3, scalar * mapped);
          }
        }
      });
      if (holes.length > 0) {
        gloss = extractGloss(holes[0], { dir: 90, range: 30 });
        gloss.forEach((a) => {
          if (a.length > 2) {
            let increment = (0.5 / splineDist(a)) * scalar;
            for (let p = 0; p <= 1; p += increment) {
              let pt = findPointAlongSpline(a, p);
              let mapped = mapQuadratic(p, 0, 1, 1, 2);
              pg.circle(offset.x + pt.x, offset.y + pt.y + scalar * 3, scalar * mapped);
            }
          }
        });
      }
    }

    if (this.features.textString.includes("1")) {
      let choice = R.choose([OVERLAY, BLEND, BLEND, BLEND, BURN]);
      pg.blendMode(choice);
      pg.blendMode(BLEND);
      let shade = extractGloss(shapes[0], { dir: 90, range: 90 });
      pg.noStroke();

      pg.fill(0, 0, 0, 1.5);
      let shadeThickness = R.next(4, 14, true);
      shade.forEach((a) => {
        if (a.length > 2) {
          let increment = (0.5 / splineDist(a)) * scalar;
          for (let p = 0; p <= 1; p += increment) {
            let pt = findPointAlongSpline(a, p);
            let mapped = mapQuadratic(p, 0, 1, 1, shadeThickness);
            for (let k = 0; k < 5; k++) {
              pg.circle(offset.x + pt.x + R.next(-scalar * 2, scalar * 2), offset.y + pt.y + R.next((-scalar * 8 * mapped) / 16, (scalar * 8 * mapped) / 16), scalar * mapped);
            }
          }
        }
      });
    }

    if (this.features.textString[5] === "1") {
      R = new Random(this.hashString);

      if (colorTone === "dark") {
        pg.blendMode(SCREEN);
      } else if (colorTone === "light") {
        pg.blendMode(BLEND);
      } else {
        pg.blendMode(SOFT_LIGHT);
      }

      let newScalar = bb.height;
      let increment = scalar * 0.01;
      let circleSize = newScalar * 0.005;

      let brights = [255, 255, 255, colorTone === "dark" ? 60 : 180];
      if (colorTone === "bright") {
        brights = [0, 0, 0, 80];
      }
      let darks = [0, 0, 0, 150];
      if (R.next() > 0.085) {
        brights = [R.next(128, 255), R.next(128, 255), R.next(128, 255), colorTone === "dark" ? 60 : 180];
        if (colorTone === "bright") {
          brights = [R.next(128, 255), R.next(128, 255), R.next(128, 255), 80];
        }
        darks = [R.next(0, 100), R.next(0, 100), R.next(0, 100), 150];
      }
      if (pixelSize === true) {
        increment = scalar * 0.2;
        circleSize = newScalar * 0.03;
      }

      pg.noStroke();
      let pts = betterShadeEdge(shapes[0], { depth: scalar * 20, ang: 180, highlight: true, increment: increment });
      pg.fill(brights);
      pts.forEach((a) => {
        pg.circle(a.x + offset.x, a.y + offset.y, circleSize);
      });
      pts = betterShadeEdge(shapes[0], { depth: scalar * 20, ang: 180, highlight: false, increment: increment });
      pg.fill(darks);
      pts.forEach((a) => {
        pg.circle(a.x + offset.x, a.y + offset.y, circleSize);
      });
      if (holes.length > 0) {
        holes.forEach((a) => {
          let pts = betterShadeEdge(a, { reversed: true, depth: scalar * 20, ang: 180, highlight: true, increment: increment });
          pg.fill(brights);
          pts.forEach((a) => {
            pg.circle(a.x + offset.x, a.y + offset.y, circleSize);
          });
          pts = betterShadeEdge(a, { reversed: true, depth: scalar * 20, ang: 180, highlight: false, increment: increment });
          pg.fill(darks);
          pts.forEach((a) => {
            pg.circle(a.x + offset.x, a.y + offset.y, circleSize);
          });
        });
      }
    }

    if (this.features.textString[6] === "1") {
      R = new Random(this.hashString);

      pg.fill(0);
      pg.blendMode(OVERLAY);

      let pos = pv(0, 0);
      let angOffset = 0;
      let d = R.next(10, 80, true);
      let len = R.next(10, 20, true);
      let increment = R.choose([30, 45, 45, 45, 60]);
      let keepRate = 1;
      let shiftRate = R.next(0, 30, true);
      let petals = [];
      let ang = R.next(-10, 10);
      for (let j = 0; j < 8; j++) {
        for (let i = 0; i < 360; i += increment) {
          let startPt = pv(pos.x + sin(radians(i + angOffset + R.next(0, shiftRate))) * d + R.next(0, shiftRate), pos.y + cos(radians(i + angOffset + R.next(0, shiftRate))) * d + R.next(0, shiftRate));
          let endPt = pointFrom(startPt, pointAng(pos, startPt) + ang, len);
          let ln = [startPt, endPt];

          if (R.next() < keepRate) {
            petals.push(ln);
          }
        }
        angOffset += 37.5;
        d += 4;
        len *= 0.93;
        increment *= 0.7;
        keepRate *= 0.9;
      }

      let bb = getBBC(petals);
      let sz = quickDist(pv(0, 0), pv(pg.width / pd, pg.height / pd));
      let flowerScalar = motherGloveScalar(bb, { motherBB: makeBBofSize(pv(0, 0), { w: sz, h: sz }), padding: 0 }) * R.next(0.05, 0.5);
      scaleArr(petals, bb.mp, flowerScalar, true);
      translateArr(petals, bb.mp, pv(0, 0), true);
      let choice = R.next();
      let colorStyle;
      if (choice > 0.98) {
        colorStyle = "random";
      } else if (choice > 0.7) {
        colorStyle = "graded";
      } else {
        colorStyle = "bw";
      }
      let stamps = R.next(1, 9, true);
      let stampPos = [];
      for (let i = 0; i < stamps; i++) {
        stampPos.push(pv(R.next(), R.next()));
