function convertRocksToPPString(shelf) {
  R = new Random(tokenData.hash);
  let alpha = "abcdefghijklmnopqrstuvwyzABCDEFGHIJKLMNOPQRSTUVWYZ0123456789";
  let parsed = new Array(16).fill(`XXXX`);
  shelf.slots.forEach((a, iterA) => {
    if (a != undefined) {
      parsed[iterA] = `${alpha[a.data.screenPos.x]}${alpha[a.data.screenPos.y]}${alpha[a.data.pos.x]}${alpha[a.data.pos.y]}`;
    } else {
      let chars = "";
      chars += "x";
      for (let i = 0; i < 3; i++) {
        chars += alpha[R.next(0, alpha.length, true)];
      }
      parsed[iterA] = chars;
    }
  });

  let shelfBoxString = `${alpha[shelf.screenPos.x]}${alpha[shelf.screenPos.y]}${alpha[shelf.pos.x]}${alpha[shelf.pos.y]}`;
  parsed[12] = shelfBoxString;
  if (shelf.orb !== undefined) {
    let orbString = `${alpha[shelf.orb.data.screenPos.x]}${alpha[shelf.orb.data.screenPos.y]}${alpha[shelf.orb.data.pos.x]}${alpha[shelf.orb.data.pos.y]}`;
    parsed[13] = orbString;
  } else {
    parsed[13] = "XXXX";
  }
  parsed[14] = "XXXX";
  parsed[15] = "XXXX";
  parsed.forEach((a, iterA) => {
    if (a.includes("XXXX")) {
      let chars = "X";
      for (let i = 0; i < 3; i++) {
        chars += alpha[R.next(0, alpha.length, true)];
      }
      parsed[iterA] = chars;
    }
  });

  let joined = parsed.join("");
  return joined;
}

function convertPPStringToRocks(ppString, { mapSearchOverride = false, bypassInfoSheet = false } = {}) {
  let alpha = "abcdefghijklmnopqrstuvwyzABCDEFGHIJKLMNOPQRSTUVWYZ0123456789";
  let items = [];
  let parsed = [];
  for (let i = 0; i < ppString.length; i += 4) {
    parsed.push(ppString.substring(i, i + 4));
  }

  let possibleRocks = parsed.slice(0, 12);
  let shelf = parsed[12];
  let orb = parsed[13];
  if (mapSearchOverride === false) {
    for (let i = 0; i < possibleRocks.length; i++) {
      if (parsed[i].includes("x")) {
        items.push(undefined);
      } else if (parsed[i].includes("X")) {
      } else {
        let screenPos = pv(alpha.indexOf(parsed[i][0]), alpha.indexOf(parsed[i][1]));
        let pos = pv(alpha.indexOf(parsed[i][2]), alpha.indexOf(parsed[i][3]));
        let sequentialIndex = world.screenSpaceToSequentialIndex({ screenPos: screenPos, pos: pos });
        let tileType = world.worldMapList[sequentialIndex];

        if (world.tileCodes.arrangeableItem.includes(tileType)) {
          items.push(new ArrangeableItem({ screenPos: screenPos, pos: pos, tileType: tileType, bypassInfoSheet: bypassInfoSheet }));
        } else {
          items.push(false);
        }
      }
    }
    if (shelf.includes("x") || shelf.includes("X")) {
      shelf = false;
    } else {
      let screenPos = pv(alpha.indexOf(shelf[0]), alpha.indexOf(shelf[1]));
      let pos = pv(alpha.indexOf(shelf[2]), alpha.indexOf(shelf[3]));
      let sequentialIndex = world.screenSpaceToSequentialIndex({ screenPos: screenPos, pos: pos });
      let tileType = world.worldMapList[sequentialIndex];
      if (world.tileCodes.nonArrangeableItem.includes(tileType)) {
        shelf = new ArrangeableItem({ screenPos: screenPos, pos: pos, tileType: tileType, bypassInfoSheet: bypassInfoSheet });
      } else {
        shelf = false;
      }
    }
    if (orb.includes("x") || orb.includes("X")) {
      orb = undefined;
    } else {
      let screenPos = pv(alpha.indexOf(orb[0]), alpha.indexOf(orb[1]));
      let pos = pv(alpha.indexOf(orb[2]), alpha.indexOf(orb[3]));
      let sequentialIndex = world.screenSpaceToSequentialIndex({ screenPos: screenPos, pos: pos });
      let tileType = world.worldMapList[sequentialIndex];
      if (world.tileCodes.nonArrangeableItem.includes(tileType)) {
        orb = new ArrangeableItem({ screenPos: screenPos, pos: pos, tileType: tileType, bypassInfoSheet: bypassInfoSheet });
      } else {
        orb = false;
      }
    }
    return { items: items, shelf: shelf, orb: orb };
  } else {
    for (let i = 0; i < possibleRocks.length; i++) {
      if (parsed[i].includes("x")) {
        items.push(undefined);
      } else if (parsed[i].includes("X")) {
      } else {
        let screenPos = pv(alpha.indexOf(parsed[i][0]), alpha.indexOf(parsed[i][1]));
        let pos = pv(alpha.indexOf(parsed[i][2]), alpha.indexOf(parsed[i][3]));
        let tileType = 50;

        if (world.tileCodes.arrangeableItem.includes(tileType)) {
          items.push(new ArrangeableItem({ screenPos: screenPos, pos: pos, tileType: tileType, bypassInfoSheet: true }));
        } else {
          items.push(false);
        }
      }
    }
    if (shelf.includes("x") || shelf.includes("X")) {
      shelf = false;
    } else {
      let screenPos = pv(alpha.indexOf(shelf[0]), alpha.indexOf(shelf[1]));
      let pos = pv(alpha.indexOf(shelf[2]), alpha.indexOf(shelf[3]));
      let tileType = 201;
      if (world.tileCodes.nonArrangeableItem.includes(tileType)) {
        shelf = new ArrangeableItem({ screenPos: screenPos, pos: pos, tileType: tileType, bypassInfoSheet: true });
      } else {
        shelf = false;
      }
    }
    if (orb.includes("x") || orb.includes("X")) {
      orb = undefined;
    } else {
      let screenPos = pv(alpha.indexOf(orb[0]), alpha.indexOf(orb[1]));
      let pos = pv(alpha.indexOf(orb[2]), alpha.indexOf(orb[3]));

      let tileType = 211;
      if (world.tileCodes.nonArrangeableItem.includes(tileType)) {
        orb = new ArrangeableItem({ screenPos: screenPos, pos: pos, tileType: tileType, bypassInfoSheet: true });
      } else {
        orb = false;
      }
    }
    return { items: items, shelf: shelf, orb: orb };
  }
}

function createIntroScreen(diggly = undefined, { frame = 18 } = {}) {
  let scalar = 0.65;

  let main = createGraphics(600 * scalar, 600 * scalar);
  main.pixelDensity(1);

  scalar = Math.min(main.width, main.height);

  let textSz = scalar * 0.1;
  let textSpacing = textSz;
  main.textSize(textSz);
  main.textAlign(CENTER, CENTER);
  let textPos = pv(main.width / 2, main.height / 3);
  main.textFont("sans-serif");
  main.textStyle(BOLD);

  main.strokeWeight(scalar * 0.01);
  main.stroke(0);
  main.fill(255);
  main.push();
  main.translate(textPos.x, textPos.y - textSpacing);
  main.rotate(radians(-7.3));
  main.textSize(textSz * 1.5);
  main.text("DIGGLY", -scalar * 0.1, -scalar * 0.05);
  main.pop();
  main.text("COLLECTS", textPos.x + scalar * 0.1, textPos.y);
  main.text("ALL", textPos.x + scalar * 0.33, textPos.y + textSpacing);

  let digglyPos = pv(main.width / 2, main.height);
  let digglyBB = [];
  for (let i in diggly.vectorFrames[frame]) {
    diggly.vectorFrames[frame][i].forEach((b) => {
      translateArr(b, pv(16, 32), pv(0, 0));
      scaleArr(b, pv(0, 0), scalar * 0.02);
      translateArr(b, pv(0, 0), digglyPos);
      digglyBB.push(getBB(b));
    });
  }

  main.strokeWeight(scalar * 0.005);
  for (let i in diggly.vectorFrames[frame]) {
    diggly.vectorFrames[frame][i].forEach((b) => {
      if (i === "head") {
        main.stroke(0);
        main.fill(diggly.features.skinColor);
      } else if (i === "eyes") {
        main.noStroke();
        main.fill(255, 255, 255, 255);
      } else if (i === "pupils") {
        main.noStroke();
        main.fill(0, 0, 0, 255);
      } else if (i === "mouth") {
        main.noStroke();
        main.fill(255, 0, 0, 255);
      } else if (i === "arms") {
        main.stroke(0);
        main.fill(diggly.features.shirtColor);
      } else if (i === "legs") {
        main.stroke(0);

        main.fill(diggly.features.pantsColor);
      } else if (i === "hair") {
        main.stroke(0);
        main.fill(diggly.features.hairColor);
      }
      pg_drawArr(b, main);
    });
  }

  let colors = [];

  colors.push(diggly.features.hairColor);
  colors.push(diggly.features.pantsColor);
  colors.push(diggly.features.shirtColor);
  colors.push(diggly.features.skinColor);
  colors.push([255, 0, 0, 255]);

  main = compressSingleFrame(main, [[0, 0, 0, 255], [255, 255, 255, 255], ...colors]);

  main.remove();

  return main;
}

function cookieCutter(shape, pg, { offset = pv(0, 0) } = {}) {
  const ctx = pg.drawingContext;
  ctx.imageSmoothingEnabled = false;
  ctx.save();
  ctx.globalCompositeOperation = "destination-in";
  pg.noStroke();
  pg.fill(255);

  pg_drawArr(shape, pg, { pos: pv(offset.x, offset.y) });
  ctx.restore();

  return pg;
}

function cookieCutterWithHoles(shapes, holes, pg, { offset = pv(0, 0) } = {}) {
  const ctx = pg.drawingContext;
  ctx.save();
  const prevSmooth = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = false;

  ctx.globalCompositeOperation = "destination-in";
  ctx.beginPath();
  for (const poly of shapes) {
    if (!poly?.length) continue;
    ctx.moveTo(poly[0].x + offset.x, poly[0].y + offset.y);

    for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i].x + offset.x, poly[i].y + offset.y);
    ctx.closePath();
  }
  ctx.fillStyle = "#fff";
  ctx.fill();

  if (holes?.length) {
    ctx.globalCompositeOperation = "destination-out";
    ctx.beginPath();
    for (const poly of holes) {
      if (!poly?.length) continue;
      ctx.moveTo(poly[0].x + offset.x, poly[0].y + offset.y);
      for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i].x + offset.x, poly[i].y + offset.y);
      ctx.closePath();
    }
    ctx.fillStyle = "#fff";
    ctx.fill();
  }

  ctx.imageSmoothingEnabled = prevSmooth;
  ctx.restore();
  return pg;
}

