function buildHashStringFromSeed(seed) {
  if (seed.length < 64) {
    do {
      seed += seed;
    } while (seed.length < 64);
    seed = "0x" + seed;
  }
  seed = seed.slice(0, 66);

  let localR = new Random(seed);
  let hashString = "";
  for (let i = 0; i < 64; i++) {
    hashString += localR.choose("0123456789abcdef");
  }
  hashString = "0x" + hashString;

  return hashString;
}

function reformatHashString(str) {
  if (str.length < 66) {
    if (str.length <= 2) {
      str = "";
      for (let i = 0; i < 64; i++) {
        str += "0";
      }
      str = "0x" + str;
    } else {
      str = str.slice(2);
      do {
        str += str;
      } while (str.length < 64);
      str = str.slice(0, 64);
      str = "0x" + str;
    }
  } else {
  }
  return str;
}

function ratioDims(ratio, { range = [10, 100] } = {}) {
  const constant = range[0] * range[1];
  const minRatio = range[0] / range[1];
  const maxRatio = range[1] / range[0];

  if (ratio < 0 || ratio > 1) {
    throw new Error(`Ratio must be between 0 and 1.`);
  }

  ratio = Math.pow(minRatio, 1 - ratio) * Math.pow(maxRatio, ratio);

  const w = Math.sqrt(constant * ratio);
  const h = Math.sqrt(constant / ratio);
  return [w, h];
}

function compressSingleFrame(frame, colorList = []) {
  frame.loadPixels();
  for (let j = 0; j < frame.height; j += 1) {
    for (let i = 0; i < frame.width; i += 1) {
      let actual = frame.get(i, j);
      if (actual[3] < 255) {
        frame.set(i, j, [0, 0, 0, 0]);
      } else if (colorList.length <= 0) {
        continue;
      } else if (actual[0] === actual[1] && actual[1] === actual[2] && actual[0] > 20 && actual[0] < 255) {
        if (actual[0] < 100) {
          let closest = getClosestColorMatch([8, 8, 8, 255], colorList);
          frame.set(i, j, closest);
        } else if (actual[0] >= 100 && actual[0] <= 200) {
          let closest = getClosestColorMatch([150, 150, 150, 255], colorList);
          frame.set(i, j, closest);
        } else if (actual[0] > 200) {
          let closest = getClosestColorMatch([255, 255, 255, 255], colorList);
          frame.set(i, j, closest);
        }
      } else {
        let closest = getClosestColorMatch(actual, colorList);
        frame.set(i, j, closest);
      }
    }
  }
  frame.updatePixels();
  return frame;
}

function outlineFrame(frame, { col = [0, 0, 0, 255] } = {}) {
  frame.loadPixels;
  for (let j = 0; j < frame.height; j++) {
    for (let i = 0; i < frame.width; i++) {
      let left = frame.get(i - 1, j);
      let right = frame.get(i + 1, j);
      let up = frame.get(i, j - 1);
      let down = frame.get(i, j + 1);
      let current = frame.get(i, j);
      if (current[3] >= 10) {
        if (left[3] < 50) {
          frame.set(i - 1, j, col);
        }
        if (right[3] < 50) {
          frame.set(i + 1, j, col);
        }
        if (up[3] < 50) {
          frame.set(i, j - 1, col);
        }
        if (down[3] < 50) {
          frame.set(i, j + 1, col);
        }
      }
    }
  }

  frame.updatePixels();
  return frame;
}

function getClosestColorMatch(rgbColor, colorList = []) {
  colorList.sort((a, b) => {
    let d1 = calculateDistanceBetween2Colors(rgbColor, a);
    let d2 = calculateDistanceBetween2Colors(rgbColor, b);
    return d1 - d2;
  });

  return colorList[0];
}

function calculateDistanceBetween2Colors(c1, c2) {
  if (c1.length < 3) {
    c1 = [c1[0], c1[0], c1[0]];
  }
  if (c2.length < 3) {
    c2 = [c2[0], c2[0], c2[0]];
  }
  if (c1.length < 4) {
    c1 = [c1[0], c1[0], c1[0], 255];
  }
  if (c2.length < 4) {
    c2 = [c2[0], c2[0], c2[0], 255];
  }
  return (c1[0] - c2[0]) ** 2 + (c1[1] - c2[1]) ** 2 + (c1[2] - c2[2]) ** 2 + (c1[3] - c2[3]) ** 2;
}

function transposeArr(arr) {
  return arr[0].map((_, colIndex) => arr.map((row) => row[colIndex]));
}

function arrIncludesPt(arr, pt) {
  for (let i = 0; i < arr.length; i++) {
