}

function rasterize(pg, { targetColor = [255, 255, 255, 255], threshold = 0 } = {}) {
  pg.loadPixels();
  for (let j = 0; j < pg.height; j++) {
    for (let i = 0; i < pg.width; i++) {
      let pix = pg.get(i, j);
      if (pix[3] > Math.floor(255 * threshold)) {
        pg.set(i, j, targetColor);
      } else {
        pg.set(i, j, [0, 0, 0, 0]);
      }
    }
  }
  pg.updatePixels();
}

function betterRectSub(arr, { count = 4, range = [0.3, 0.6], rng = undefined, style = 4 } = {}) {
