      target = 0;
    } else if (tar === "random") {
      target = rng.next(0, rects.length - 1, true);
    }

    let bb = getBB(rects[target]);
    let splitVertically = bb.width / bb.height < 1;
    let newRect1, newRect2;
    if (splitVertically === false) {
      let newX = bb.p1.x + (bb.p2.x - bb.p1.x) * rng.next(range[0], range[1]);
      bars.push([pv(newX, bb.p1.y), pv(newX, bb.p4.y)]);
      newRect1 = cloneArrRecursive([bb.p1, pv(newX, bb.p1.y), pv(newX, bb.p4.y), bb.p4])[0];
      newRect2 = cloneArrRecursive([pv(newX, bb.p1.y), bb.p2, bb.p3, pv(newX, bb.p4.y)])[0];
    } else {
      let newY = bb.p1.y + (bb.p4.y - bb.p1.y) * rng.next(range[0], range[1]);
      bars.push([pv(bb.p1.x, newY), pv(bb.p2.x, newY)]);
      newRect1 = cloneArrRecursive([bb.p1, bb.p2, pv(bb.p2.x, newY), pv(bb.p1.x, newY)])[0];
      newRect2 = cloneArrRecursive([pv(bb.p1.x, newY), pv(bb.p2.x, newY), bb.p3, bb.p4])[0];
    }

    rects.splice(target, 1);
