function quantizeColors(r, g, b, { step = 15, max = 255 } = {}) {
  r = Math.round(r / step) * step;
  r = Math.max(0, Math.min(max, r));
  g = Math.round(g / step) * step;
  g = Math.max(0, Math.min(max, g));
  b = Math.round(b / step) * step;
  b = Math.max(0, Math.min(max, b));
  a = 255;
  if (r === g && g === b) {
    if (r === 0) {
      r = 15;
      g = 15;
      b = 15;
    } else if (r === 255) {
      r = 225;
      g = 225;
      b = 225;
    }
  }
  return [r, g, b, a];
}

function findPointInShape(arr, { tries = 100, rng = undefined } = {}) {
  let bb = getBB(arr);
  let count = 0;
  searchLoop: while (true) {
    let ptFac = pv(rng.next(0, 1), rng.next(0, 1));

    let pt = pv(bb.p1.x + (bb.p2.x - bb.p1.x) * ptFac.x, bb.p2.y + (bb.p3.y - bb.p2.y) * ptFac.y);
    if (pointInsideShape(pt, arr)) {
      return pt;
    }
    count++;
    if (count >= tries) {
      break searchLoop;
    }
  }
  return false;
}

