  cutter.push(pv(cutter[cutter.length - 1].x, cutter[cutter.length - 1].y + bb.height));
  cutter.push(pv(cutter[0].x, cutter[0].y + bb.height));
  closeOpenShape(cutter);
  trim1 = trimLineBy(crv, { knife: cutter }).outside;
  trim2 = trimLineBy(cutter, { knife: crv }).inside;
  trim1 = [...trim1, ...trim2];
  trim1 = mendCurvesAlt(trim1);
  trim1.sort((a, b) => {
