    if (main.fade >= 255) {
      main.state = 25;
      main.loadingTimer = 0;
      main.cheapPixels = undefined;
      main.introScreenA = undefined;
      main.introScreenB = undefined;
      main.fade = 255;
      main.fadeDir = "in";
      main.textPos = pv(width / 2, height / 2);
      main.stateTimer = 3000;
    }
  }

  main.stateTimer--;

  if (main.stateTimer <= 0) {
    main.keysDisabled = false;
    main.stateTimer = 0;
  }
}

function storyScreen() {
  background(0);
  textAlign(CENTER, CENTER);
  fill(255);
  noStroke();
  let tSize = Math.min(width, height) * 0.025;
  textSize(tSize);

  let textLines = [`Diggly the digger, with shovel so bright,`, `Digs deep in the dirt from the morning till night!`, `He finds rocks that are round, in pretty colors of hue,`, `Rocks speckled and sparkly, in shapes old and new.`, ``, `Diggly dreams of a shelf, oh so tall and so grand,`, `Where his rocks can all shine for the world to command.`, `But the choices are many, and the spots are too few—`, `He needs a good friend, and that friend is YOU!`, ``, `Now you are Diggly, with shovel in hand,`, `Dig far and dig wide across the whole land!`, `Pick the prettiest pebbles, your favorite of the day,`, `Arrange them with care in a meaningful way.`, ``, `Place 'em and sort 'em, let the wonders unfold,`, `Make that shelf sparkle brighter than stories of old!`, `For Diggly and you, in this diggy delight,`, `The rocks will all shine in the wonderful light!`];

  textLines.forEach((a, iterA) => {
    text(a, main.textPos.x, main.textPos.y + iterA * tSize * 1.5);
  });
  main.textPos.y -= Math.min(width, height) * 0.00025;

  main.stateTimer--;

  if (main.stateTimer <= 0) {
    main.fadeDir = "out";
  }
  fill(0, main.fade);
  noStroke();
  rect(0, 0, width, height);
  if (main.fadeDir === "in") {
    main.fade -= 2;
    if (main.fade <= 0) {
      main.fade = 0;
      main.fadeDir = "none";
    }
  } else if (main.fadeDir === "out") {
    main.fade += 4;
    if (main.fade >= 255) {
      main.state = 30;
      main.loadingTimer = 0;
    }
  }

  main.loadingTimer = 0;
}

function gameLoadingScreen() {
