}

function mainGameLoop() {
  background(0);
  master.displayScreen();
  player.displayPlayer();
  if (player.userControlQueue.length <= 0) {
    player.inactivityTimer++;
  }
  if (main.userControl === false) {
    let path;
    if (player.isIdle === true && player.userControlQueue.length <= 0) {
      let choice = R.next();
      if (choice < 0) {
        path = [];
        player.userControlQueue = [];
      } else if (choice < 0.5) {
        path = master.assignRandomPath(player, master.screen.safeBin);
      } else {
        path = master.calculatePathToExit(player, master.screen.safeBin);
      }
      player.userControlQueue = [];
      player.userControlQueue.push(...path);
    } else if (player.isIdle === true && player.userControlQueue.length > 0) {
      player.userControlQueue.shift();
    }
    if (player.animationFreeze.active === true) {
    } else {
      player.moveStep(player.userControlQueue[0]);
    }
  } else if (main.userControl === true) {
    if (player.animationFreeze.active === true) {
    } else {
      player.interpretUserControlKeyPress();
      let queue = player.userControlQueue[0];
      player.moveStep(queue, { turnFace: false });
    }
  }

  master.displayScreenFrame();
}

