function writeTextStringToFile() {
  let hash = convertRocksToPPString(player.itemBag.cabinets[player.itemBag.activeShelf].realShelf);
  let writer = createWriter("hash.txt");
  writer.write(`DIGGLY COLLECTS ALL\n\n`);
  writer.write(`The following text string represents a rock and shelf arrangement. \n\n\n`);
  writer.write(hash);
  writer.write(`\n\n\n^^^^^^ Copy and paste this text string into the DIGGLY COLLECTS ALL artwork interface on the ArtBlocks.io website.\n`);
  writer.write(`Doing so will set this rock and shelf arrangement as the default token artwork.\n`);
  writer.write(`The token owner must be logged in to the website using the wallet that holds the token while performing this action.\n`);
  writer.write(`A gas transaction fee may be required in order to submit the text string to the blockchain.\n\n`);
  writer.write(`-----------------------------------\n\n`);
  writer.write(`\n\n\n`);
  writer.write(`Here are some additional details about this rock and shelf arrangement.\n\n`);

  let activeShelf = player.itemBag.cabinets[player.itemBag.activeShelf].realShelf;
  let activeOrb = player.itemBag.cabinets[player.itemBag.activeShelf].realShelf.orb;
  writer.write(`BACKDROP:\n\n`);
  if (activeOrb !== undefined) {
    writer.write(` - color style: ${activeOrb.item.features.colorStyle}\n`);
    writer.write(` - wall style: ${activeOrb.item.features.wallStyle}\n`);
    writer.write(` - floor style: ${activeOrb.item.features.floorStyle}\n`);
    writer.write(` - collected from screen ${activeOrb.data.screenPos.x},${activeOrb.data.screenPos.y} at position ${activeOrb.data.pos.x},${activeOrb.data.pos.y}\n`);
  } else {
    writer.write(` - no backdrop applied\n`);
  }
  writer.write(`\n\n`);
  writer.write(`SHELF:\n\n`);
  writer.write(` - capacity: ${activeShelf.features.capacity}\n`);
  writer.write(` - style: ${activeShelf.features.styleNames[activeShelf.features.shelfStyle]}\n`);

  if (!activeShelf.features.textString.includes("1")) {
  } else {
    for (let i = 0; i < activeShelf.features.textString.length; i++) {
      if (activeShelf.features.textString[i] === "1") {
        writer.write(` - ${activeShelf.features.textureStyles[i]}\n`);
      }
    }
  }
  writer.write(` - collected from screen ${activeShelf.screenPos.x},${activeShelf.screenPos.y} at position ${activeShelf.pos.x},${activeShelf.pos.y}\n`);

  writer.write(`\n\n`);
  writer.write(`The shelf contains the following items:\n`);

  activeShelf.slots.forEach((a, iterA) => {
    writer.write(`\n - Slot ${iterA}\n`);
    if (a !== undefined) {
      writer.write(`      ROCK (${a.itemData.features.type})\n`);
      for (let i = 0; i < a.itemData.features.textString.length; i++) {
        if (a.itemData.features.textString[i] === "1") {
          writer.write(`       -- ${a.itemData.features.textureStyles[i]}\n`);
        }
      }
      writer.write(`       -- collected from screen ${a.data.screenPos.x},${a.data.screenPos.y} at position ${a.data.pos.x},${a.data.pos.y}\n`);
    } else {
      writer.write(`      empty\n`);
    }
  });

  writer.write(`\nThis arrangement is unique to the following token hash: ${tokenData.hash}`);

  writer.close();
}

