function soundByte_mouseClick(tone = 600) {
  if (hud.audioEnabled === true) {
    playTone(R.next(tone - 1, tone + 1), { duration: 0.25, type: "square", volume: 0.2 });
  }
}

function keyPressed() {
  if (main.keysDisabled === true) {
    return;
  }
  let escapeKeys = ["Escape", "Enter", " "];
  if (main.state === 0) {
    return;
  }

  if (escapeKeys.includes(key)) {
    if (main.state === 40) {
      hud.clearSelection();
    }
    if (main.state === 5) {
      customPPString = undefined;
      ppStringToggle = false;

      main.state = 0;
      main.stateTimer = 100;
      main.keysDisabled = true;
      return;
    }
    if (main.state === 10) {
      ppStringToggle = false;
      main.state = 19;

      main.stateTimer = 0;
      main.keysDisabled = true;
      loop();
      return;
    }
    if (main.state === 40 || main.state === 41) {
      main.showMap = false;
    }
    if (main.state === 80) {
      main.state = 40;
      main.artGeneratorComplete = false;
      main.artGeneratorIndex = 0;
      customPPString = undefined;
      arrangement = undefined;
      loop();
      return;
    }
  }

  if (main.state === 10 || main.state === 80) {
    if (key === "s") {
      if (main.state === 80) {
        let scalar = Math.min(width, height);
        let subsection = get(arrangement.realBB.p1.x - scalar * 0.05, arrangement.realBB.p1.y - scalar * 0.05, arrangement.realBB.width + scalar * 0.1, arrangement.realBB.height + scalar * 0.1);
        subsection.save(`Diggly${tokenData.tokenId}.png`);
        subsection = null;
      } else {
        save(`Diggly${tokenData.tokenId}.png`);
      }
    }
  }

  if (main.state === 20) {
    if (main.fadeDir !== "out") {
      main.fadeDir = "out";
    }
    return;
  }

  if (main.state === 25) {
    main.fadeDir = "out";

    return;
  }
  if (main.state === 30) {
    return;
  }
  if (main.state === 40) {
    main.showUserControlInfo = false;

    if (key === "p") {
      world.enableWalkOnWater();
      player.walkOnWater = true;
    }

    if (key === "1") {
      hud.active = !hud.active;
    }

    if (key === "x") {
      main.paused = !main.paused;
      if (main.paused === false) {
        main.state = 40;
        loop();
      }
      return;
    }

    if (key === "m") {
      main.showMap = !main.showMap;
      return;
    }

    if (key === " ") {
      player.dig();
      hud.clearSelection();
      return;
    }

    if (key === "Shift" || key === "Enter" || key === "b") {
      player.crouchAndPickup();
      hud.clearSelection();
      return;
    }
  }

  if (main.state === 40 || main.state === 41) {
    let arrowKeys = ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "a", "w", "s", "d"];
    if (arrowKeys.includes(key) && main.userControl === false) {
      player.switchToUserControl();
      return;
    } else if (arrowKeys.includes(key) && main.userControl === true) {
      hud.clearSelection();
      if (main.state === 41) {
        main.state = 40;
        main.activeRock = undefined;
        player.animationFreeze.type = "";
        player.animationFreeze.active = false;
        player.animationFreeze.timer = 0;
        player.animationFreeze.disableUserControl = false;
      }
      player.showInventoryFull = false;
      return;
    }
  }

  if (main.state === 70) {
    return;
  }
}

function keyReleased() {
  if (main.state === 40) {
    if (key === "ArrowUp" || key === "w") {
      player.userControlQueue = player.userControlQueue.filter((item) => item !== "up");
      player.inactivityTimer = 0;
    }
    if (key === "ArrowDown" || key === "s") {
      player.userControlQueue = player.userControlQueue.filter((item) => item !== "down");
      player.inactivityTimer = 0;
    }
    if (key === "ArrowLeft" || key === "a") {
      player.userControlQueue = player.userControlQueue.filter((item) => item !== "left");
      player.inactivityTimer = 0;
    }
    if (key === "ArrowRight" || key === "d") {
      player.userControlQueue = player.userControlQueue.filter((item) => item !== "right");
      player.inactivityTimer = 0;
    }
  }
}

function mouseClicked() {
  if (main.state === 40) {
    if (main.showMap === true) {
            main.showMap = false;
      return;
    }
    hud.checkForClick();
  }
  if (main.state === 41) {
    if (main.showMap === true) {
            main.showMap = false;
      return;
    }
    hud.checkForClick();
  }
  if (main.state === 80) {
    main.buttons.forEach((a, iterA) => {
      if (mouseX > a.p1.x && mouseX < a.p2.x && mouseY > a.p2.y && mouseY < a.p3.y) {
        if (main.buttonGroup[iterA] === "exit") {
          main.state = 40;
          main.artGeneratorComplete = false;
          main.artGeneratorIndex = 0;
          customPPString = undefined;
          arrangement = undefined;
          return;
        } else if (main.buttonGroup[iterA] === "download") {
          writeTextStringToFile();
        }
      }
    });
  }
}

function loadGameAssets() {
  if (customPPString !== undefined && ppStringToggle === true) {
    arrangement = new Arrangement(customPPString, { bypassInfoSheet: true, mapSearchOverride: false });

    if (arrangement.invalidMap === true) {
      return false;
    }

    if (ppStringCanvasRatio === undefined) {
      ppStringCanvasRatio = [arrangement.bbVector.width, arrangement.bbVector.height];
      let ww = window.innerWidth;
      let wh = window.innerHeight;
      ww * (ppStringCanvasRatio[1] / ppStringCanvasRatio[0]) > wh ? resizeCanvas(wh * (ppStringCanvasRatio[0] / ppStringCanvasRatio[1]), wh) : resizeCanvas(ww, ww * (ppStringCanvasRatio[1] / ppStringCanvasRatio[0]));

      arrangement = new Arrangement(customPPString, { bypassInfoSheet: true, mapSearchOverride: false });
      textAlign(CENTER, CENTER);
      fill(255);
      noStroke();
      text("LOADING ARTWORK", width / 2, height / 2);
    }
  } else {
    let spriteSheet = new SpriteSheetBuilder();

    sprites.sheet.sheetImage = spriteSheet.fetchSpriteSheet();
    spriteSheet = undefined;
    master = new Master();
    player = new Player({ spawnPt: world.spawnPt });
    hud = new HUD();

    if (customPPString !== undefined) {
      let convertedPPString = convertPPStringToRocks(customPPString, { bypassInfoSheet: false, mapSearchOverride: false });
      let rocks = convertedPPString.items;
      let shelf = convertedPPString.shelf;
      let orb = convertedPPString.orb;
      player.itemBag.loadPlayerWithPPStringItems(rocks, shelf, orb);
    } else {
      player.itemBag.givePlayerStartingShelf();
      player.itemBag.givePlayerStartingOrb();
    }
  }
}

function setup() {
  scaleAgnosticCanvas([window.innerWidth, window.innerHeight]);

  injectCSS();

  background(0);
  textSize(Math.min(width, height) * 0.03);
  textAlign(CENTER, CENTER);
  fill(255);
  noStroke();
  textFont("Courier New");
  text("INITIALIZING...", width / 2, height / 2);

  ppStringToggle = true;
}

function draw() {
  if (main.paused === false) {
    if (main.state === 0) {
      ppLoadingScreen();
    } else if (main.state === 5) {
      invalidPPScreen();
    } else if (main.state === 10) {
      ppShelfViewerScreen();
    } else if (main.state === 19) {
      gameIntroLoading();
    } else if (main.state === 20) {
      gameIntroScreen();
    } else if (main.state === 25) {
      storyScreen();
    } else if (main.state === 30) {
      gameLoadingScreen();
    }
    if (main.state === 40) {
      mainGameLoop();
      if (hud.active === true) {
        hud.display();
      }
      if (main.showUserControlInfo === true) {
        userControlInfoScreen();
      }
      if (main.showMap === true) {
        world.drawWorldAsPixels(master.screen.data.screenPos, player.pos.current);
      }
    } else if (main.state === 41) {
      obtainedARockScreen();
      if (hud.active === true) {
        hud.display();
      }
    } else if (main.state === 70) {
      loadingScreen();
    } else if (main.state === 80) {
      shelfPreviewScreen();
    }
  } else {
    fill(0, 0, 0);
    text("PAUSED", width / 2 + 2, height / 2 + 2);
    fill(255, 255, 255);
    text("PAUSED", width / 2, height / 2);
  }
  if (hud !== undefined) {
    ap.playSoundQueue();
  }
}

function processPostParamsData() {
  const pp = tokenData.externalAssetDependencies[0];
  let ppInputTextString = pp.data["Custom Arrangement Text String"] || undefined;

  ppInputTextString = validateString(ppInputTextString);
  return ppInputTextString;
}

function validateString(str) {
  if (str !== undefined) {
    let acceptableChars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

    str = str.trim();
    if (str.length !== 64) {
      str = undefined;
      return str;
    }

    for (let i = 0; i < str.length; i++) {
      if (!acceptableChars.includes(str[i])) {
        str = undefined;
        return str;
      }
    }
    return str;
  }
  return undefined;
}

function processUrlParams() {
  let urlParams = new URLSearchParams(window.location.search);
  let urlObj = {};

  if (urlParams.has("ppString")) {
    urlObj.ppString = validateString(urlParams.get("ppString"));
  } else {
    urlObj.ppString = undefined;
  }

  const VALID_SIZES = new Set([16, 32, 64, 128]);
  const DEFAULT_SIZE = 32;

  if (urlParams.has("spriteSize")) {
    const rawValue = urlParams.get("spriteSize");

    const numValue = parseInt(rawValue, 10);

    if (Number.isInteger(numValue) && VALID_SIZES.has(numValue)) {
      urlObj.spriteSize = numValue;
    } else {
      urlObj.spriteSize = DEFAULT_SIZE;
    }
  } else {
    urlObj.spriteSize = DEFAULT_SIZE;
  }

  return urlObj;
}
